let data,storageMode,ui={view:'explore',region:'motion',mission:'rover-rescue',activeAdventure:'motion',adventures:{},harborWalk:null,feedback:null,choice:null,animation:null,progress:0,paused:false,visualMode:'schematic',mapStyle:'illustrated',cinema:{activeId:'motion',isPlaying:false,currentTime:0,speed:1,muted:false,theaterMode:false},lab:{adapter:'ramp',input:.2,trials:[],options:{},coop:false},arcade:null,word:null,clip:null,dictQuery:''},saveError=false,saveConflict=false,swUpdate=null;
