function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function save(type='checkpoint',payload={}){try{await persist(data,{profile:data.active,mission:ui.mission,type,...payload});saveError=false;saveConflict=false;const warning=$('#save-conflict-warning');if(warning)warning.style.display='none';const status=$('#save-status');if(status)status.textContent='Saved on this device';}catch(error){saveError=true;saveConflict=error.code==='SAVE_CONFLICT';const warning=$('#save-conflict-warning');if(warning)warning.style.display=saveConflict?'block':'none';notify(error.code==='SAVE_CONFLICT'?error.message:'Progress could not be saved. Export a backup in Settings before closing.');const status=$('#save-status');if(status)status.textContent='Save failed — export a backup';}}
function goto(view,extras={}){stopAnimation();stopCinema();stopClip();if(view!=='harbor-walk'&&view!=='teach-path'&&!(profile().teachPath?.enabled&&['mission','capstone'].includes(view)&&currentMission()?.region==='motion'))stopHarborWalk();if(view!=='adventure-3d')stopAdventure3D();if(view!=='harbor-walk'&&view!=='adventure-3d')document.body?.classList.remove('is-immersive-3d');ui.word=null;ui.clip=null;if(view==='region'&&(extras.region??ui.region)==='motion')ensureHarborRuntime(profile());Object.assign(ui,{view,feedback:null,choice:null,progress:0},extras);if(view!=='mission')save('navigation');render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function startMission(id){if(!byId[id])return;if(!canStartPathMission(profile(),id)){notify('Pip: meet the idea and finish the earlier checks first.');openTeachPath();return;}ui.mission=id;profile().runs[id]??=createRun(byId[id]);const r=migrateRun(profile().runs[id]);if(r.stage==='done')ui.progress=1;data.lastMission=id;profile().lastMission=id;save('mission-open');goto('mission',{mission:id,progress:r.trials.length?1:0,choice:checkpoint(r).choice,feedback:checkpoint(r).feedback});}
const wordsMet=()=>profile().wordsMet||{};
function meetWord(term){const p=profile();p.wordsMet??={};if(p.wordsMet[term])return;p.wordsMet[term]=Date.now();save('word-met',{term});}
function filmUnlocked(doc){return wordsMetFor(filmWords(doc),wordsMet())&&(!(profile().teachPath?.enabled&&doc.id==='motion')||unitClear(profile(),4));}
function formulasTaught(doc){return profile().teachPath?.enabled&&doc.id==='motion'?unitClear(profile(),4):!!profile().runs[doc.missionId]?.completed;}
let clipTimer=null;
function stopClip(){if(clipTimer){cancelAnimationFrame(clipTimer);clipTimer=null;}if(ui.clip)ui.clip.playing=false;}
function paintClip(){const c=ui.clip&&clipById(ui.clip.id);if(!c)return;const stage=$('#clip-stage'),caption=$('#clip-caption'),btn=$('#clip-play-btn');if(stage)stage.innerHTML=clipFrame(c,ui.clip.t);if(caption)caption.textContent=ui.clip.t>=c.duration-2.6?c.sentence:'';if(btn)btn.textContent=ui.clip.playing?'⏸ Pause':ui.clip.t>=c.duration?'↺ Watch again':ui.clip.t>0?'▶ Resume':'▶ Play clip';}
function playClip(){const c=ui.clip&&clipById(ui.clip.id);if(!c)return;if(ui.clip.playing){stopClip();paintClip();return;}if(ui.clip.t>=c.duration)ui.clip.t=0;if(reading().reduced||matchMedia('(prefers-reduced-motion: reduce)').matches){ui.clip.t=c.duration;paintClip();return;}ui.clip.playing=true;let last=performance.now();const tick=now=>{if(!ui.clip?.playing)return;ui.clip.t=Math.min(c.duration,ui.clip.t+Math.min(.1,(now-last)/1000));last=now;if(ui.clip.t>=c.duration){ui.clip.playing=false;clipTimer=null;paintClip();return;}paintClip();clipTimer=requestAnimationFrame(tick);};paintClip();clipTimer=requestAnimationFrame(tick);}
function openWord(term,clipId=null){if(!glossary[term])return;stopClip();ui.word=term;ui.clip=clipId&&clipById(clipId)?{id:clipId,t:0,playing:false}:null;meetWord(term);render();$('#word-title')?.focus({preventScroll:true});if(ui.clip)playClip();}
function closeWord(){const term=ui.word;stopClip();ui.word=null;ui.clip=null;render();if(term)(document.querySelector(`#main [data-term="${CSS.escape(term)}"]`))?.focus({preventScroll:true});}
function achievements(){return missions.filter(m=>profile().runs[m.id]?.completed).length;}
function shell(body){let p=profile();return `<div class="game-shell"><header class="topbar"><button class="brand" data-action="nav" data-view="explore" aria-label="Science Quest home"><span class="brand-mark">✦</span><span>SCIENCE <strong>QUEST</strong><small>DISCOVERY ISLANDS</small></span></button><div class="top-actions"><button class="cinema-top-btn" data-action="nav" data-view="cinema" aria-label="Open Science Cinema"><span>🎬</span><span>Cinema</span></button><button class="cinema-top-btn" data-action="nav" data-view="dictionary" aria-label="Open the Dictionary"><span>📖</span><span>Dictionary</span></button><span class="discovery-count">✧ ${achievements()}<span> discoveries</span></span><button class="profile-button" data-action="nav" data-view="settings"><span>${esc(p.avatar)}</span> ${esc(p.name)}</button><button class="icon-button" data-action="nav" data-view="settings" aria-label="Settings">⚙</button></div></header>${!navigator.onLine?'<div class="offline">Offline exploration · progress saves on this device</div>':''}<div id="save-conflict-warning" class="offline" role="alert" style="display:${saveConflict?'block':'none'}">Another tab saved newer progress. Export this tab’s backup before reloading, then import it to preserve both versions. ${button('Export this tab’s backup','export','secondary')}</div>${swUpdate?`<div class="offline">An island update is ready. ${button('Save & update','update')}</div>`:''}<main id="main" tabindex="-1">${body}</main><nav class="bottom-nav" aria-label="Game modes">${[['explore','⌖','Explore'],['cinema','🎬','Cinema'],['lab','⚒','Build'],['test','▷','Test'],['journal','▤','Journal'],['arcade','✧','Arcade']].map(([id,icon,name])=>`<button data-action="nav" data-view="${id}" class="${ui.view===id||(id==='test'&&ui.view==='mission')||(id==='explore'&&ui.view==='region')?'active':''}" ${ui.view===id?'aria-current="page"':''}><span>${icon}</span>${name}</button>`).join('')}</nav><footer><span id="save-status">${saveError?'Save failed — export a backup':'Saved on this device'}</span><span>Science Quest 1.48 · Early access</span></footer></div>`;}
function heading(eyebrow,title,copy='',actions=''){return `<div class="section-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${copy?`<p class="intro">${copy}</p>`:''}</div>${actions}</div>`;}
function reading(){return readingPreferences(profile(),data.settings);}
function recommended(){if(profile().teachPath?.enabled)return byId[nextTeachUnit(profile()).mission||'keep-it-fair'];const last=profile().lastMission||data.lastMission;return (last&&!profile().runs[last]?.completed?byId[last]:null)||(reading().band!=='All explorers'?missions.find(m=>m.band===reading().band&&!profile().runs[m.id]?.completed):null)||missions.find(m=>m.id==='rover-rescue'&&!profile().runs[m.id]?.completed)||missions.find(m=>!profile().runs[m.id]?.completed)||byId['rover-rescue'];}
function worldOverlay(){const owned=new Set((profile().world?.upgrades||[]).map(x=>x.id));return `<svg class="world-upgrades" viewBox="0 0 1000 540" role="img" aria-label="Island restoration: ${worldUpgrades.filter(x=>owned.has(x.id)).map(x=>x.name).join(', ')||'no facilities restored yet'}">${worldUpgrades.map(u=>{const x=u.x*10,y=u.y*5.4,done=owned.has(u.id);return `<g transform="translate(${x} ${y})" opacity="${done?1:.45}"><title>${u.name}: ${done?'restored':'awaiting discovery'}</title><ellipse cy="12" rx="16" ry="5" fill="#174752" opacity=".3"/><rect x="-12" y="-8" width="24" height="20" rx="3" fill="${done?'#ffe09a':'#536f75'}" stroke="${done?'#fff4c8':'#c2d3cb'}" stroke-width="2"/><path d="M-16-8L0-20 16-8Z" fill="${done?'#e3a93e':'#687e82'}"/><text y="7" text-anchor="middle" font-size="17" fill="${done?'#27585c':'#d4dcd2'}">${u.icon}</text>${done?'<circle cx="14" cy="-17" r="5" fill="#baf0a3" stroke="#245f57"/>':''}</g>`;}).join('')}</svg>`;}
function workshopView(){reconcileWorld(profile());const w=profile().world;return `<section class="content">${heading('YOUR RESTORED WORKSHOP','Make room for discoveries.','Place the rewards earned through your experiments. Decorations never unlock essential instruction.')}<div class="workshop-room">${workshopSlots.map(slot=>{const item=decorations.find(d=>d.id===w.placements[slot]);return `<div class="workshop-slot"><div class="workshop-object">${item?item.icon:'◇'}</div><h2>${slot}</h2><p>${item?item.name:'Choose a decoration below'}</p><label class="field">Place a reward<select data-placement="${slot}" aria-label="Decoration for ${slot}"><option value="">Choose a decoration</option>${decorations.filter(d=>w.decorations.includes(d.id)).map(d=>`<option value="${d.id}" ${item?.id===d.id?'selected':''}>${d.name}</option>`).join('')}</select></label></div>`;}).join('')}</div><h2>Island restoration</h2><div class="upgrade-grid">${worldUpgrades.map(u=>{const earned=w.upgrades.some(x=>x.id===u.id);return `<article class="upgrade-card ${earned?'earned':''}"><span>${u.icon}</span><div><h3>${u.name}</h3><p>${earned?'Restored by your discovery':'Restore through '+byId[u.mission].title}</p>${button(earned?'Revisit mission':'Open mission','start','text-button',`data-id="${u.mission}"`)}</div></article>`;}).join('')}</div></section>`;}
function activeCoop(){return(data.coopSessions||[]).find(x=>x.id===data.coopActive);}
function coopView(){const session=activeCoop();if(!session)return `<section class="content">${heading('SHARE AN INVESTIGATION','Co-op Lab','Choose two to four local explorers. Each person records their own prediction and explanation.')}<form id="coop-setup" class="settings-panel"><h2>Choose your team</h2>${data.profiles.map(p=>`<label class="toggle"><input name="coop-player" type="checkbox" value="${p.id}">${esc(p.avatar)} ${esc(p.name)}</label>`).join('')}<label class="field">Investigation<select id="coop-mission">${missions.map(m=>`<option value="${m.id}">${m.title}</option>`).join('')}</select></label><button class="primary" type="submit" ${data.profiles.length<2?'disabled':''}>Start shared investigation</button>${data.profiles.length<2?button('Add another explorer','nav','secondary','data-view="settings"'):''}</form>${data.coopSessions?.length?`<h2>Saved shared investigations</h2>${data.coopSessions.map(s=>button(byId[s.mission]?.title+' · round '+(s.round+1),'coop-resume','secondary',`data-id="${s.id}"`)).join('')}`:''}</section>`;
const m=byId[session.mission],model=adapters[m.adapter],actor=currentCoopActor(session),actorProfile=data.profiles.find(p=>p.id===actor),last=session.trials.at(-1),roles=rolesFor(session);let panel='';
if(['predict','explain'].includes(session.stage)){const q=m.questions[session.stage];panel=`<p class="eyebrow">PASS THE DEVICE</p><h2>${esc(actorProfile.name)}’s ${session.stage==='predict'?'prediction':'explanation'}</h2><p>${esc(q.prompt)}</p><div class="choices">${q.options.map((option,i)=>button(esc(option),'coop-choice','choice '+(session.draft===i?'selected':''),`data-value="${i}" aria-pressed="${session.draft===i}"`)).join('')}</div>${button('Record my '+(session.stage==='predict'?'prediction':'explanation'),'coop-answer','primary full',Number.isInteger(session.draft)?'':'disabled')}${button('Help with this idea','coop-hint','text-button')}${session.help[session.stage][actor]?`<p class="assistance">Supported response. Pip: ${esc(q.options[q.correct])}</p>`:''}<p class="muted">Answers stay hidden until everyone has explained. One team result never awards everyone mastery.</p>`;}
else if(session.stage==='experiment'){panel=`<p class="eyebrow">TEAM EXPERIMENT</p><h2>Build, test and compare.</h2><p>Builder: ${esc(data.profiles.find(p=>p.id===roles.find(r=>r.role==='Builder').profile).name)}. Change only ${model.control}. Try ${m.compare[0]} and ${m.compare[1]} ${model.unit}.</p><label class="field">${model.input}<input id="coop-input" type="range" min="${model.min}" max="${model.max}" step="${model.step}" value="${session.input}"><output>${session.input} ${model.unit}</output></label><p class="fixed">${model.fixed}</p>${button(esc(data.profiles.find(p=>p.id===roles.find(r=>r.role==='Tester').profile).name)+': run test','coop-run','primary full')}${button('Each explorer explains →','coop-explain','secondary full',fairPair(session.trials)?'':'disabled')}`;}
else{panel=`<h2>Everyone contributed.</h2><p>Your shared experiment is saved. Individual answers are in each explorer’s journal; the team’s completion does not mark anyone’s mission mastered.</p>${session.roster.map(id=>{const p=data.profiles.find(p=>p.id===id),a=session.answers.predict[id],b=session.answers.explain[id];return `<div class="coop-summary"><b>${esc(p.name)}</b><p>Prediction: ${a.correct?'supported by the model':'revise with the results'}${a.assisted?' · used help':''}<br>Explanation: ${b.correct?'fits the evidence':'practice this idea'}${b.assisted?' · used help':''}</p></div>`;}).join('')}${button('Rotate roles & investigate again','coop-next','primary full')}${button('Choose another investigation','coop-new','secondary full')}`;}
return `<section class="content">${heading('ROUND '+(session.round+1)+' / SHARED DEVICE',m.title,'Prediction → shared experiment → individual explanation',button('Other shared labs','coop-new','secondary'))}<div class="coop-banner">${roles.map(r=>`<span><b>${r.role}</b>: ${esc(data.profiles.find(p=>p.id===r.profile)?.name||'Explorer')}</span>`).join(' · ')}</div><div class="lab-layout"><div class="lab-main"><div class="scene-card"><div class="scene-header">Shared simulation · ${model.label}</div>${scene(m.adapter,last?.input??session.input,last,last?1:0)}</div><div class="evidence-panel"><h2>Team trial record</h2>${trialTable(session.trials,m.adapter,true)}${timeSeries(last,m.adapter)}</div>${modelCard(m.adapter)}</div><aside class="task-panel">${panel}</aside></div></section>`;}
function mapView(){const next=recommended();return `<section class="world-wrap">${teachPathEntry()}<div class="world-top"><div><p class="eyebrow">YOUR NEXT GREAT DISCOVERY</p><h1>A little curiosity.<br>A whole world to restore.</h1></div><div class="world-top-right"><button class="map-style-btn" data-action="toggle-map-style" aria-label="Toggle realistic aerial satellite map">${ui.mapStyle==='satellite'?'🗺 Show Field Map':'🛰 Realistic Satellite Map'}</button><span class="world-weather">☀ &nbsp; A good day for science</span></div></div><div class="world-map"><img class="island-art ${ui.mapStyle==='satellite'?'satellite-art':''}" src="${ui.mapStyle==='satellite'?'./assets/discovery_islands_hero.jpg':'./assets/islands.webp'}" alt="A research archipelago with a rover harbor, materials workshop, biodome, weather ridge, signal lighthouse and observatory connected by bridges." fetchpriority="high"><div class="map-vignette"></div>${worldOverlay()}<div class="map-label">DISCOVERY ISLANDS <span>FIELD MAP / 01</span></div>${regions.map(r=>{const count=missions.filter(m=>m.region===r.id&&profile().runs[m.id]?.completed).length;return `<button class="map-pin ${count?'restored':''}" style="left:${r.x}%;top:${r.y}%;--region:${r.color}" data-action="region" data-id="${r.id}" aria-label="Explore ${r.name}, ${count} discoveries"><i>${r.icon}</i><span>${r.name}<small>${count?`${count} discoveries made`:'Explore region →'}</small></span></button>`;}).join('')}<div class="map-coordinate">27.4° N &nbsp; / &nbsp; 6 RESEARCH REGIONS</div><div class="recommend"><span class="mission-emblem">${regionOf(next).icon}</span><div><p class="eyebrow">${profile().runs[next.id]&&!profile().runs[next.id].completed?'CONTINUE YOUR EXPEDITION':'PIP’S PICK'}</p><h2>${esc(next.title)}</h2><p>Make a prediction. Build. Test. Discover.</p></div>${button(profile().runs[next.id]&&!profile().runs[next.id].completed?'Resume mission →':'Start mission →','start','primary',`data-id="${next.id}"`)}</div></div><div class="under-map"><div class="pip-mini">${robotSvg()}<p><strong>“Every good question is a place to start.”</strong><br>I’m Pip, your field assistant. Pick an island or join me at the rover ramp.</p></div><div>${button('🚶 Harbor Walk (3D) →','nav','primary','data-view="harbor-walk"')}${button('📖 Dictionary →','nav','secondary','data-view="dictionary"')}${button('🎬 Science Cinema →','nav','secondary','data-view="cinema"')}${button('My workshop','nav','secondary','data-view="workshop"')}${button('Learning pathways →','nav','secondary','data-view="courses"')}${button('Meet the islands ↓','islands','text-button')}</div></div><div id="region-grid" class="region-grid">${regions.map(r=>`<button class="region-card" data-action="region" data-id="${r.id}" style="--region:${r.color}"><span class="region-icon">${r.icon}</span><strong>${r.name}</strong><span>${r.description}</span><small>${missions.filter(m=>m.region===r.id).length} missions &nbsp; →</small></button>`).join('')}</div></section>`;}
function robotSvg(){return `<svg viewBox="0 0 80 85" class="pip-icon" aria-hidden="true">${robot(40,40)}</svg>`;}
function coursesView(){return `<section class="content">${heading('CHOOSE YOUR ROUTE','Learning pathways','Start where you are ready. Grade labels guide the route; every guided mission remains available.')}<div class="course-grid">${pathways.map(p=>{const progress=pathwayProgress(p,profile());return `<article class="mission-card"><div class="card-top">${badge('Grade '+p.grade)}${badge(progress.completed+' / '+progress.total+' investigations')}</div><h2>${p.title}</h2><p>${p.focus}</p>${p.grade==='11'?button('Analyze motion records →','motion-data-open','secondary'):''}${['11','12'].includes(p.grade)?button('Build an energy model →','energy-model-open','secondary'):''}${p.grade==='12'?button('Power an island outpost →','energy-cap-open','secondary')+button('Read observed climate records →','climate-open','secondary'):''}<ol class="course-missions">${p.missions.map(id=>{const m=byId[id],r=profile().runs[id];return `<li>${button((r?.completed?'✓ ':'')+m.title,'start','text-button',`data-id="${id}"`)}<small>${skillState(r)}</small></li>`;}).join('')}</ol><details class="model-card"><summary>Course scope and development</summary><p>This route currently covers the investigations above, not a complete grade curriculum. Still being developed: ${p.next.join('; ')}.</p></details></article>`;}).join('')}</div><section class="math-library"><h2>Quick math bridges</h2><p>Short practice for the quantities and units used in science. Return to your investigation when ready.</p>${Object.entries(mathBridges).map(([id,b])=>button((profile().mathBridges?.[id]?.complete?'✓ ':'')+b.title,'math-open','secondary',`data-id="${id}"`)).join('')}</section></section>`;}
function contextLinks(m){const family=missions.filter(v=>v.contextFamily===m.id);if(!family.length)return '';return `<details class="context-links"><summary>Two companion investigations · ${family.filter(v=>profile().runs[v.id]?.completed).length} of 2 discoveries</summary>${family.map(v=>`<p><strong>${esc(v.title)}</strong><br>${button(profile().runs[v.id]?.completed?'Revisit →':profile().runs[v.id]?'Resume →':'Begin →','start','secondary',`data-id="${v.id}"`)} ${badge(skillState(profile().runs[v.id]))}</p>`).join('')}</details>`;}
function regionView(){const r=regions.find(r=>r.id===ui.region),list=missions.filter(m=>m.region===r.id),count=list.filter(m=>profile().runs[m.id]?.completed).length;return `<section class="content">${button('← Discovery Islands','nav','back','data-view="explore"')}${heading('FIELD EXPEDITION',r.name,r.description,`<div class="region-heading-icon" style="background:${r.color}">${r.icon}</div>`)}<div class="region-banner" style="--region:${r.color}"><div><b>${count===list.length?r.reward:'Restore this part of the island network'}</b><p>${count} of ${list.length} discoveries · Guided missions are always available.</p></div><div class="region-banner-actions"><button class="cinema-banner-btn adventure-launch-btn" data-action="open-3d-adventure" data-region="${r.id}" aria-label="Explore ${r.name} in 3D">🎮 Walk & Explore (3D) →</button><button class="cinema-banner-btn" data-action="watch-video" data-region="${r.id}" aria-label="Watch ${r.name} documentary">🎬 Watch ${r.name} Video (${cinemaById(r.id).duration}s)</button></div><progress value="${count}" max="${list.length}" aria-label="Region restoration"></progress></div>${r.id==='motion'?teachPathEntry()+harborView(profile(),{selected:ui.harborSite,fresh:ui.harborFresh?.profile===data.active?ui.harborFresh.ids:[]})+harborReplayView():''}<h2>Guided discoveries</h2><div class="mission-grid">${list.filter(m=>!m.contextFamily).map(m=>{const run=profile().runs[m.id],s=skillState(run);return `<article class="mission-card"><div class="card-top"><span class="mission-number">${String(m.index+1).padStart(2,'0')}</span>${badge(run?.completed?'✓ Discovery made':m.band+' pathway',run?.completed?'success':'')}</div><h2>${m.title}</h2><p>${m.story}</p>${contextLinks(m)}<div class="mission-meta">${m.minutes} min · ${m.skill}</div><div class="card-foot">${badge(s,s==='Demonstrated'||s==='Retained'?'success':'')}${button(run&&!run.completed?'Resume →':run?.completed?'Revisit →':'Explore →','start','secondary',`data-id="${m.id}"`)}</div></article>`;}).join('')}</div></section>`;}
function questionFor(m,r){const stage=r.stage,transfer=transferPlan(m,r);if(transfer?.question)return equivalentItem(m,stage,r.attempts[stage]||0)??transfer.question;const fresh=equivalentItem(m,stage,r.attempts[stage]||0);if(fresh)return earlyQuestion(m,r,fresh);let q;
 if(stage==='predict')q=r.attempts.predict>0?m.questions.t1:m.questions.predict;
 if(stage==='build')q=Q(`Which setup makes a fair test of ${adapters[m.adapter].control}?`,`Change only ${adapters[m.adapter].control}; keep the other conditions the same.`,`Change ${adapters[m.adapter].control} and the starting object together.`,'Change every setting to see a bigger difference.');
 if(stage==='compare'){const pair=selectedTrials(r);if(pair.length===2){const [a,b]=pair;const relation=b.value>a.value?'greater than':b.value<a.value?'less than':'equal to';q=Q(`Compare Trial ${r.trials.indexOf(a)+1} and Trial ${r.trials.indexOf(b)+1}. The measured ${adapters[m.adapter].output.toLowerCase()} in the second is…`,`${relation} the first.`,`${relation==='greater than'?'less than':'greater than'} the first.`,'Impossible to compare using the recorded measurements.');}}
 if(stage==='explain')q=r.attempts.explain>0?m.questions.t2:m.questions.explain;
 if(stage==='transfer1')q=m.questions.t1;
 if(stage==='transfer2')q=m.questions.t2;
 return earlyQuestion(m,r,q);
}
function choices(q,r){if(!q)return '';const rotation=(currentMission().index+r.stage.length+(r.attempts[r.stage]||0))%q.options.length;const options=q.options.map((text,i)=>({text,i}));options.push(...options.splice(0,rotation));return `<div class="question"><h2>${linkTerms(esc(q.prompt),profile().wordsMet||{})}</h2><div class="choices" role="group" aria-label="Answer choices">${options.map(o=>{const cue=reading().pictures?pictureCue(currentMission(),q,o.i):null;return `<div class="answer-row"><button class="choice ${ui.choice===o.i?'selected':''}" data-action="choice" data-value="${o.i}" aria-pressed="${ui.choice===o.i}"><span class="choice-dot">${ui.choice===o.i?'●':'○'}</span>${cue?`<span class="picture-cue" aria-hidden="true"><b>${cue.svg||esc(cue.picture)}</b><small>${esc(cue.label)}</small></span>`:''}<span>${esc(o.text)}</span></button><button class="read-choice" data-action="read-choice" data-value="${o.i}" aria-label="Read this choice: ${esc(o.text)}">◖ Listen</button></div>`;}).join('')}</div></div>`;}

function lesson(m){if(m.lesson)return m.lesson;const lessons={ramp:'Watch a rover roll down a ramp. Starting higher gives it more gravitational energy to transfer into motion. On the same stopping lane, a higher start goes farther. A fair test changes height only.',push:'A contact push is a force. It can change motion. Compare a gentle and a stronger push on the same cart for the same amount of time. Start each trial from rest.',direction:'A push has a direction as well as a strength. Start a cart at rest and push left, then reset and push right. A direction test keeps strength, duration and the cart unchanged.',force:'Opposing forces act in different directions. Equal opposing forces give zero net force. A resting cart stays at rest; an already-moving cart keeps its velocity in our resistance-free model.',resistance:'Rolling resistance acts against motion and slows the rover. At the same entry speed, stronger resistance brings it to rest sooner. Its energy transfers to the surroundings.',collision:'A moving cart has kinetic energy. For equal masses, a faster cart carries more. When a soft barrier stops it, energy transfers into deformation, heating and sound.',thermal:'Warm and cool regions can transfer energy through a material. Conductivity describes how readily that transfer occurs. A lower conductivity gives less heat transfer each second for the same wall and temperatures.',matter:'Choose the system boundary: everything inside our sealed container. If nothing enters or leaves, the total mass of the contents is conserved when they are mixed or change state.',plant:'Plants need suitable conditions. Our fictional species grows best at an intermediate light level, not at the highest possible light. Compare three plants per condition while keeping water, soil and temperature unchanged.',habitat:'An organism needs resources. A food budget compares available food with food needed by each animal. Real habitats also involve water, shelter and interactions; food alone cannot predict a population.',runoff:'Rainwater can run across a surface or stay in the ground. Our model gives more retention with more vegetation. Keep rain, soil and slope fixed when testing cover.',wave:'A wave repeats. Frequency counts cycles per second; wavelength is the distance between corresponding points on consecutive cycles. At a fixed speed, higher frequency means shorter wavelength.',energy:'Power is an energy-transfer rate, measured in watts. Energy in watt-hours equals watts multiplied by hours. Only a fraction of the stored energy reaches the loads; the rest transfers to the surroundings.',orbit:'An orbit repeats around a central body. In this circular-orbit model around a Sun-like star, larger radii have longer periods. The relationship changes if the central mass changes.'};return lessons[m.adapter];}
function trialTable(trials,adapter,compact=false){const model=adapters[adapter];if(!trials.length)return '<p class="empty">Your results will appear here after your first test.</p>';return `<div class="table-scroll"><table><caption class="sr-only">Recorded experiment measurements</caption><thead><tr><th>Trial</th><th>${model.input} ${model.unit?`(${model.unit})`:''}</th><th>${model.output} (${model.outUnit})</th>${compact?'':'<th>Replay</th>'}</tr></thead><tbody>${trials.map((t,i)=>`<tr><th scope="row">${i+1}</th><td>${round(t.input)}</td><td>${round(t.value)}</td>${compact?'':`<td><button class="tiny" data-action="replay" data-index="${i}" aria-label="Replay trial ${i+1}">▷</button></td>`}</tr>`).join('')}</tbody></table></div>`;}
function timeSeries(result,adapter){if(stoppingAdapters[adapter])return stoppingRecord(result);if(chemistryCourseAdapters[adapter])return chemistryCourseRecord(result,adapter);if(adapter.startsWith('ecosystem-'))return ecosystemRecord(result,adapter);if(adapter==='water-cycle')return waterCycleRecord(result);if(physicsAdapters[adapter])return physicsRecord(adapter,result);if(result&&['rainfall','plate-motion','rock-clock','planet-balance','star-radiation'].includes(adapter)){const labels={volume:'Collected water (mL)',area:'Collector area (cm²)',daughter:'Daughter isotope (%)',absorbed:'Absorbed flux (W/m²)',reflected:'Reflected flux (W/m²)',emitted:'Emitted flux (W/m²)',temperature:'Effective temperature (K)',reference:'Reference temperature (K)'},rows=Object.entries(result).filter(([k])=>labels[k]).map(([k,v])=>[labels[k],round(v)]);if(['plate-motion','rock-clock'].includes(adapter))rows.push(...result.series.map(p=>[`${round(p.t)} ${result.timeUnit}`,`${round(p.x)} ${adapters[adapter].outUnit}`]));return `<details class="model-card" open><summary>Earth and space model record</summary><table><tbody>${rows.map(([label,value])=>`<tr><th>${esc(label)}</th><td>${esc(value)}</td></tr>`).join('')}</tbody></table></details>`;}if(result&&['photosynthesis','respiration','expression','population','selection'].includes(adapter)){let rows;if(adapter==='expression')rows=[['Coding DNA (5′→3′)',result.dna.join(' ')],['mRNA (5′→3′)',result.rna.join(' ')],['Protein fragment',result.protein.join(' – ')]];else if(['population','selection'].includes(adapter))rows=result.series.map(p=>[`${adapter==='selection'?'Generation':'Model time'} ${p.t}`,round(p.x)+(adapter==='selection'?'%':' expected individuals')]);else rows=Object.entries(result).filter(([k,v])=>typeof v==='number'&&!['duration','value','input','modelVersion'].includes(k)).map(([k,v])=>[({glucose:'Glucose-equivalent molecules',waterLeft:'Water molecules left',oxygen:'Oxygen molecules produced',carbonAtoms:'Total carbon atoms',hydrogenAtoms:'Total hydrogen atoms',oxygenAtoms:'Total oxygen atoms',glucoseLeft:'Glucose molecules left',oxygenLeft:'Oxygen molecules left',water:'Water molecules produced',carbonDioxide:'Carbon dioxide molecules produced'})[k]||k,round(v)]);return `<details class="model-card" open><summary>Biology model record</summary><table><tbody>${rows.map(([label,value])=>`<tr><th>${esc(label)}</th><td>${esc(value)}</td></tr>`).join('')}</tbody></table></details>`;}if(result&&['melting','sieve','isotope','stoichiometry','bond-energy'].includes(adapter)){const fields={melting:{'Liquid mass (kg)':result.liquidMass,'Solid mass (kg)':result.solidMass,'Temperature (°C)':result.temperature},sieve:{'Above mesh (g)':result.above,'Below mesh (g)':result.below,'Small grains below (g)':result.small,'Large grains below (g)':result.large,'Small-grain purity (%)':result.purity},isotope:{Protons:result.protons,Neutrons:result.neutrons,Electrons:result.electrons,'Mass number':result.value},stoichiometry:{'Water molecules':result.water,'Hydrogen molecules left':result.hydrogenLeft,'Oxygen molecules left':result.oxygenLeft,'Hydrogen atoms total':result.hydrogenAtoms,'Oxygen atoms total':result.oxygenAtoms},'bond-energy':{'Energy required (kJ/mol reaction)':result.broken,'Energy released (kJ/mol reaction)':result.formed,'Net enthalpy (kJ/mol reaction)':result.value}}[adapter];return `<details class="model-card" open><summary>Model accounting table</summary><table><tbody>${Object.entries(fields).map(([label,value])=>`<tr><th>${label}</th><td>${round(value)}</td></tr>`).join('')}</tbody></table></details>`;}if(result?.ledger)return `<details class="model-card" open><summary>Interval energy ledger</summary><div class="table-scroll"><table><thead><tr><th>Hours</th><th>Load W</th><th>Demand Wh</th><th>Served Wh</th><th>Unserved Wh</th><th>Remaining Wh</th></tr></thead><tbody>${result.ledger.map(p=>`<tr><td>${p.hours}</td><td>${round(p.watts)}</td><td>${round(p.required)}</td><td>${round(p.served)}</td><td>${round(p.missing)}</td><td>${round(p.remaining)}</td></tr>`).join('')}</tbody></table></div><p>Conversion transfer to surroundings: ${round(result.loss)} Wh. Delivered reserve: ${result.reserve} Wh. Power limit: ${result.powerLimit} W.</p>${result.lowerMargin!==undefined?`<p>Margin bounds: ${round(result.lowerMargin)} to ${round(result.upperMargin)} Wh. Nominal: ${round(result.nominalMargin)} Wh. These are specified bounds, not confidence probabilities.</p>`:''}</details>`;if(result?.genotypes)return `<details class="model-card"><summary>Offspring probability table</summary><table><caption>Expected genotype proportions</caption><thead><tr><th>Genotype</th><th>Probability</th></tr></thead><tbody>${Object.entries(result.genotypes).map(([g,p])=>`<tr><th>${g}</th><td>${p}%</td></tr>`).join('')}</tbody></table><p>Expected proportions do not guarantee exact small-group outcomes.</p></details>`;if(adapter==='diffusion'&&result)return `<details class="model-card"><summary>Membrane exchange record</summary><table><caption>Dye concentration, units/L, in two one-litre compartments</caption><thead><tr><th>Time (s)</th><th>Inside</th><th>Outside</th></tr></thead><tbody>${result.series.filter((_,i)=>i%10===0).map(p=>`<tr><td>${p.t}</td><td>${round(p.x)}</td><td>${round(p.outside)}</td></tr>`).join('')}</tbody></table><p>Total dye: ${result.total} units. Equilibrium concentration: ${result.value} units/L in both compartments.</p></details>`;if(adapter==='circuit'&&result)return `<details class="model-card"><summary>Circuit measurements</summary><p>Current: ${round(result.value)} A. Power transferred to resistor: ${round(result.power)} W. Source voltage: 6 V.</p></details>`;if(adapter==='density'&&result)return `<p class="model-card">The sample ${result.state==='floats'?'floats':result.state==='neutral'?'is neutrally buoyant':'sinks'}. Fully submerged is not the same as floating.</p>`;if(!result||!['plant','energy','wave','orbit'].includes(adapter))return '';const m=adapters[adapter];let rows=result.series;if(rows.length>15)rows=rows.filter((_,i)=>i%10===0);return `<details class="model-card"><summary>${adapter==='plant'?'Daily growth record & replicates':'Model data record'}</summary><div class="table-scroll"><table><thead><tr><th>${result.timeUnit||'Model time (s)'}</th><th>${adapter==='wave'?'Displacement (relative)':adapter==='orbit'?'x-position (AU)':adapter==='energy'?'Delivered energy balance (Wh)':'Mean height (cm)'}</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${round(p.t)}</td><td>${round(p.x)}</td></tr>`).join('')}</tbody></table></div>${result.replicates?`<p>Day 7 replicates: ${result.replicates.map(x=>round(x)+' cm').join(' · ')}. Mean ${round(result.value)} cm.</p>`:''}${adapter==='energy'?`<p>Delivered: ${result.delivered} Wh · demand: ${result.demand} Wh · conversion transfer to surroundings: ${result.loss} Wh.</p>`:''}</details>`;}
function controls(adapter,input,locked=false,options={}){const m=adapters[adapter],simple=ui.view==='mission'?earlyControl(currentMission(),input):null,label=simple?.label||m.input;return `<div class="controls"><div class="control-label"><label for="experiment-input">${label}</label><output id="input-output">${simple?simple.value+' ('+input+' '+m.unit+')':(input+' '+m.unit)}</output></div><div class="slider-row">${button('−','adjust','adjust',`data-delta="-1" aria-label="Decrease ${label}" ${locked?'disabled':''}`)}<input id="experiment-input" type="range" min="${m.min}" max="${m.max}" step="${m.step}" value="${input}" ${locked?'disabled':''} aria-label="${label}">${button('+','adjust','adjust',`data-delta="1" aria-label="Increase ${label}" ${locked?'disabled':''}`)}</div><div class="range-ends"><span>${simple?.low??(m.min+' '+m.unit)}</span><span>${simple?.high??(m.max+' '+m.unit)}</span></div><p class="fixed">⌑ ${esc(options.fixed??(adapter==='ramp'&&options.resistance?m.fixed+' · Free Lab resistance override: '+options.resistance:m.fixed))}</p></div>`;}
function modelCard(adapter){const m=adapters[adapter];return `<details class="model-card"><summary>Model assumptions & science notes</summary><p>${m.limits}</p><details><summary>Show the relationship</summary><p class="formula">${m.law}</p></details><p class="muted">Teaching model v1 · Exact values in the journal; display values rounded.</p></details>`;}
const stages=['notice','predict','build','test','compare','explain','transfer1','transfer2','done'];const stageNames={notice:'Notice',predict:'Predict',build:'Build a fair test',test:'Test',compare:'Compare',explain:'Explain',transfer1:'Apply · new context',transfer2:'Apply · new constraint',done:'Discovery'};
function energyBuilder(r){const draft=r.energyDraft||{supply:'',demand:'',margin:''};const op=(id)=>`<select id="energy-${id}" aria-label="${id} operation"><option value="">Choose operation</option>${[['+','add'],['*','multiply'],['-','subtract'],['/','divide']].map(([v,t])=>`<option value="${v}" ${draft[id]===v?'selected':''}>${t}</option>`).join('')}</select>`;return `<div class="model-editor"><h3>Construct your energy model</h3><p>Use units to assemble the model before running the night.</p><label class="field">Delivered energy: storage ${op('supply')} efficiency</label><label class="field">Demand: load ${op('demand')} hours</label><label class="field">Margin: delivered energy ${op('margin')} demand</label>${button(r.energyModel?'✓ Model checked':'Check my model','energy-check','secondary full')}<p class="muted">${r.energyModel?'Your constructed model is ready to test.':'Power (W) multiplied by time (h) gives energy (Wh).'}</p></div>`;}
function routeCapstoneView(){const r=currentRun(),c=r.capstone??=createRouteCapstone(currentMission().capstone??'harbor'),d=routeSteps[c.phase],a=c.answers[c.phase]||{},result=c.trials.at(-1),value=result||routeModel(c.config,c.brief),shown=result?.config||c.config,b=routeBrief(c.brief);return `<section class="content">${button('← Return to Motion Harbor','region','back','data-id="motion"')}${heading('HARBOR CAPSTONE',c.complete?'The route works.':d.title,'One connected model: ramp energy → braking lane → stopping cushion.')}<p>${esc(currentMission().title)}: reach the cushion ${b.distance} m beyond the ramp, with ${b.minEnergy}–${b.maxEnergy} J arrival energy. Keep average stopping force at or below ${b.maxForce} N and ramp height at or below ${b.maxHeight.toFixed(2)} m.</p><div class="lab-layout"><div><div class="scene-card"><svg viewBox="0 0 800 300" role="img" aria-label="Route design: ${value.reaches?'reaches':'does not reach'} the cushion; arrival energy ${round(value.arrivalEnergy)} joules; average force ${round(value.averageForce)} newtons"><rect width="800" height="300" fill="#deeeea"/><path d="M60 90L230 220H700" fill="none" stroke="#557f80" stroke-width="12"/><rect x="620" y="150" width="${shown.cushion*200}" height="70" fill="#ecc56c"/><rect x="${value.reaches?580:350}" y="185" width="40" height="25" rx="5" fill="#e4a541"/><text x="50" y="270" fill="#21454c" font-size="19">Height ${shown.height} m · resistance ${shown.resistance} · cushion ${shown.cushion} m</text></svg></div><table><caption>${result?'Latest saved test':'Untested starting preview'} · connected energy and force ledger</caption><tbody>${[['Starting energy',value.initialEnergy,'J'],['Lane transfer',value.laneLoss,'J'],['Arrival energy',value.arrivalEnergy,'J'],['Average cushion force',value.averageForce,'N']].map(([label,x,u])=>`<tr><th>${label}</th><td>${round(x)} ${u}</td></tr>`).join('')}</tbody></table><p>${value.success?'✓ All final constraints met':'Keep testing the design constraints.'}</p><p class="muted">Ideal 2 kg cart, lossless ramp, constant rolling resistance. Cushion average force = arrival energy / stopping distance. Peak force and real material behavior are not predicted. Diagram is schematic.</p><details><summary>${c.trials.length} saved route trials</summary>${c.trials.map(t=>`<p>Step ${t.phase+1}: h ${t.config.height} m, resistance ${t.config.resistance}, cushion ${t.config.cushion} m → ${round(t.arrivalEnergy)} J, ${round(t.averageForce)} N</p>`).join('')}</details></div><aside class="task-panel">${c.complete?`<h2>Three connected decisions tested.</h2><p>All final constraints pass. Your predictions, explanations and controlled trials are saved.</p>${button('Finish the mission','cap-finish','primary')}`:`<h2>${d.predict}</h2>${d.options.map((text,i)=>button(text,'cap-answer','choice',`data-kind="predict" data-value="${i}"`)).join('')}<p>${a.predict?(a.predict.correct?'Prediction fits the model.':'Revisit the model before testing.'):'Choose your prediction.'}</p><label class="field">${d.title}<input id="cap-setting" type="range" min="${d.min}" max="${d.max}" step="${d.step}" value="${c.config[d.key]}"><output>${c.config[d.key]} ${d.unit}</output></label>${button('Run route test','cap-test','primary',a.predict?.correct?'':'disabled')}${capstonePair(c)?`<h3>${d.explain}</h3>${d.explanations.map((text,i)=>button(text,'cap-answer','choice',`data-kind="explain" data-value="${i}"`)).join('')}<p>${a.explain?(a.explain.correct?'Explanation recorded.':'Look again at the energy ledger.'):'Choose your explanation.'}</p>${button(c.phase===2?'Verify complete route':'Next design decision','cap-next','secondary',a.explain?.correct?'':'disabled')}`:'<p>Run two trials changing only this step’s setting.</p>'}`}</aside></div></section>`;}
function missionView(){const seen=new Set(),m=currentMission(),r=currentRun(),model=adapters[m.adapter],q=questionFor(m,r),transfer=transferPlan(m,r),last=(transfer?transferTrials(r):r.trials).at(-1),interactive=r.stage==='test',display=ui.replay??last;
 let panel='';
 if(r.stage==='notice')panel=`<p class="eyebrow">MISSION BRIEF</p><h2>${m.title}</h2><p>${linkTerms(m.story,wordsMet(),seen)}</p><div class="pip-note">${robotSvg()}<p>${linkTerms(lesson(m),wordsMet(),seen)}</p></div><div class="mission-words"><b>Meet the words</b><p>Tap a word to see what it means. A ▶ word has a short clip.</p>${wordChips(missionWords(m),wordsMet())}</div><div class="bridge"><b>Before we begin</b><p>${linkTerms('Near and far compare positions. A trial is one test. A fair comparison changes one thing.',wordsMet(),seen)}</p>${m.prerequisites.length?`<p>Helpful preparation: ${m.prerequisites.map(id=>`<button class="term" data-action="start" data-id="${id}">${byId[id].title}</button>`).join(', ')}</p>`:''}</div>${button('Make a prediction →','next','primary full')}`;
 else if(r.stage==='test')panel=`<p class="eyebrow">YOUR EXPERIMENT</p><h2>${m.target?'Find a design that works':'Change one thing. Watch closely.'}</h2><p>${m.target?`Target: ${m.target[0]}–${m.target[1]} ${model.outUnit} (${model.output.toLowerCase()}).`:`Try ${m.compare[0]} and ${m.compare[1]} ${model.unit}. Keep everything else fixed.`}</p>${m.constraint?`<p class="constraint">${esc(m.constraint)}</p>`:''}${m.adapter==='energy'?energyBuilder(r):''}${controls(m.adapter,r.input,!!ui.animation,transfer?{...transfer.options,fixed:transfer.fixed}:{} )}${plannedTrialButtons(m,r)}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume test':'Pause'):'Run test','run','primary',m.adapter==='energy'&&!r.energyModel?'disabled':'')}${button('Reset scene','reset','secondary')}</div><p class="muted">${r.trials.length} saved trial${r.trials.length===1?'':'s'} · reset keeps your evidence.</p>${last?`<div class="result-card"><small>${model.output}</small><strong>${round(last.value)} ${model.outUnit}</strong>${m.target?`<span>${missionDesignSatisfied(m,last)?'✓ Meets the design brief':'↻ Try another setting'}</span>`:''}</div>`:''}${!canCompare(m,r)?'<p class="compare-help" role="status">Choose two different-setting trials in the notebook below, with other conditions fixed'+(m.target?', including a design that meets the target':'')+'.</p>':''}${button('Compare my evidence →','compare','secondary full',(!canCompare(m,r)||ui.animation)?'disabled':'')}`;
 else if(r.stage==='done'){const state=skillState(r),all=CATEGORIES.every(k=>r.evidence[k]);panel=`<div class="completion-icon">✦</div><p class="eyebrow">DISCOVERY RECORDED</p><h2>${r.completed?'A little more of the island is alive.':'Your evidence is recorded.'}</h2><p>${esc(m.skill)} · ${r.completed?'mission complete':'keep investigating'}</p>${badge(state,all?'success':'')}<p>${all?'You predicted, made a fair test, interpreted, explained, and applied the idea in two new contexts.':'Your discovery is saved. Some checks used help; revisit those checks to demonstrate the idea independently.'}</p><div class="evidence-grid">${CATEGORIES.map(k=>`<span class="${r.evidence[k]?'earned':''}">${r.evidence[k]?'✓':'○'} ${k.replace('transfer','Apply ')}</span>`).join('')}</div>${!all?button('Practice checks needing evidence','retry','primary full'):button('Explore the next mission →','next-mission','primary full')}${(m.id==='restore-route'||m.capstone)?button(r.capstone?.complete?'Revisit route design':'Build the connected route','cap-open','secondary full'):''}${(missions.some(v=>v.contextFamily===m.id)||m.contextFamily)?`<h3>Try another investigation in this family</h3>${missions.filter(v=>v.id!==m.id&&(v.id===(m.contextFamily||m.id)||v.contextFamily===(m.contextFamily||m.id))).map(v=>button(v.title,'start','secondary full',`data-id="${v.id}"`)).join('')}`:''}${(()=>{const doc=cinemaById(m.region);return doc.missionId===m.id||r.completed?(filmUnlocked(doc)?button(`🎬 Your reward film: ${esc(doc.regionName)}`,'watch-video','secondary full',`data-region="${doc.id}"`):`<p class="muted">The ${esc(doc.regionName)} film opens after you meet its words: ${filmWords(doc).filter(t=>!wordsMet()[t]).map(t=>`<button class="term" data-action="term" data-term="${esc(t)}">${esc(t)}</button>`).join(', ')}.</p>`):'';})()}${m.region==='motion'?button('See Motion Harbor →','region','primary full','data-id="motion"'):''}${button('Open field journal','nav','secondary full','data-view="journal"')}`;}
 else panel=`<p class="eyebrow">${stageNames[r.stage].toUpperCase()}</p>${transfer?`<h2>${transfer.title}</h2><p>${linkTerms(transfer.story,wordsMet(),seen)}</p><p class="constraint">${transfer.constraint||`New bay: ${transfer.target[0]}–${transfer.target[1]} m beyond the exit.`}</p>${controls(m.adapter,r.input,!!ui.animation,transfer?{...transfer.options,fixed:transfer.fixed}:{} )}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume test':'Pause'):'Test transfer design','run','primary')}${button('Reset scene','reset','secondary')}</div>${last?`<div class="result-card"><small>${model.output}</small><strong>${round(last.value)} ${model.outUnit}</strong><span>${transferSatisfied(m,r)?'✓ A tested design meets this brief':'Revise the setting and test again'}</span></div>`:''}${trialTable(transferTrials(r),m.adapter,true)}${timeSeries(last,m.adapter)}`:''}${r.stage==='build'&&supportsFairSetup(m)?fairSetupView(m,r):''}${r.stage==='build'&&needsPlan(m)?planMarkup(r):''}${choices(q,r)}${r.stage==='predict'?`<label class="note-label">Why do you think so? (optional)<textarea id="prediction-note" rows="2" maxlength="1000" placeholder="I think… because…">${esc(r.predictionNote||'')}</textarea></label><p class="muted">Your words are saved for discussion, not automatically graded.</p>`:''}${r.stage==='explain'?`<label class="note-label">Your own explanation (optional; saved for adult review)<textarea id="explanation" rows="3" maxlength="1000" placeholder="I noticed… My evidence is…">${esc(r.notes)}</textarea></label><p class="muted">Writing is saved, not automatically graded. Use the evidence choice above for this check.</p>`:''}${ui.feedback?`<div class="feedback ${ui.feedback.ok?'good':'try'}" role="status">${esc(ui.feedback.text)}</div>`:''}${ui.feedback?.ok?button('Continue →','next','primary full'):button('Check my idea','check','primary full',ui.choice===null||!transferSatisfied(m,r)||ui.animation?'disabled':'')}${button('A little help','hint','text-button')}${r.assistance[r.stage]?'<p class="assistance">Supported attempt · this check will need an independent retry.</p>':''}`;
 const visibleInput=ui.progress>0?(display?.input??r.input):r.input;
 const resultArea=`<div class="scene-header"><span class="live-dot"></span><span>${model.label}</span><span>${ui.animation?ui.paused?'Paused':'Test running':ui.progress===1?'Trial recorded':'Ready to investigate'}</span><button class="visual-mode-toggle" data-action="toggle-visual-mode" aria-label="Toggle realistic artwork and shader rendering">${ui.visualMode==='realistic'?'📐 Schematic':'🛰 Realistic'}</button></div><div id="scene">${scene(m.adapter,visibleInput,display,ui.progress,transfer?.target??m.target,r.trials.at(-2),transfer?.options||{},{...m,visualMode:ui.visualMode})}</div><div class="scene-caption">${m.adapter==='plant'?'Seven simulated days · three plants per condition':m.adapter==='energy'?'Ten simulated hours · solar output is zero at night':(m.adapter==='ramp'||model.rampVariant)?'Schematic · vertical scale exaggerated · distance measured from ramp exit':'One setting changes. One useful question.'}</div>`;
 return `<section class="content mission-content">${button('← '+regionOf(m).name,'region','back',`data-id="${m.region}"`)}<div class="mission-title"><div><p class="eyebrow">${regionOf(m).name.toUpperCase()} / EXPERIMENT ${String(m.index+1).padStart(2,'0')}</p><h1>${m.title}</h1></div>${button('◖ Read aloud','narrate','secondary')}${button('Stop reading','stop-reading','text-button')}</div><ol class="stepper" aria-label="Mission progress">${stages.map((s,i)=>`<li class="${stages.indexOf(r.stage)>=stages.indexOf(s)?'reached':''} ${r.stage===s?'current':''}" ${r.stage===s?'aria-current="step"':''}><span>${i+1}</span>${s==='transfer1'?'Apply':s==='transfer2'?'Apply again':stageNames[s]}</li>`).join('')}</ol><div class="lab-layout"><div class="lab-main"><div class="scene-card">${resultArea}</div>${r.trials.length?`<div class="evidence-panel"><div class="panel-heading"><h2>Your trial notebook</h2>${badge(r.trials.length+' saved')}</div>${chart(r.trials)}${r.stage==='test'?`<div class="evidence-picker"><h3>Choose two trials to compare</h3><p class="muted">Change one setting. Keep the other conditions the same.</p>${r.trials.map((t,i)=>button(`${(r.compareSelection||[]).includes(t.id)?'✓':'○'} Trial ${i+1}: ${round(t.input)} ${model.unit}`,'select-trial',(r.compareSelection||[]).includes(t.id)?'secondary selected':'secondary',`data-id="${t.id}" aria-pressed="${(r.compareSelection||[]).includes(t.id)}"`)).join('')}</div>`:''}${trialTable(r.trials,m.adapter)}${m.adapter==='plant'?plantEvidence(r.trials,r.compareSelection):m.adapter.startsWith('trait-')?traitEvidence(r.trials):timeSeries(last,m.adapter)}</div>`:''}${modelCard(m.adapter)}<details class="model-card"><summary>Meet the idea / glossary</summary><p>${lesson(m)}</p>${wordChips(missionWords(m),wordsMet())}${button('Open the Dictionary','nav','text-button','data-view="dictionary"')}</details></div><aside class="task-panel" aria-label="Current mission step">${panel}<details class="model-card"><summary>Need a quick math bridge?</summary><p>${mathBridges[bridgeForMission(m)].intro}</p>${button(mathBridges[bridgeForMission(m)].title,'math-open','secondary full',`data-id="${bridgeForMission(m)}"`)}</details></aside></div></section>`;
}
function canCompare(m,r){return hasSelectedFairPair(r)&&r.trials.some(t=>missionDesignSatisfied(m,t));}
function harborReplayView(){const t=ui.harborReplayProfile===data.active?ui.harborReplay:null;if(!t)return '';return `<section class="scene-card harbor-replay" aria-label="Saved delivery replay"><h2>Replay your saved delivery</h2><p>Recorded ramp height: ${round(t.input)} m · delivery distance: ${round(t.value)} m. This replay adds no trials or skill evidence.</p><div id="scene">${scene('ramp',t.input,t,ui.progress,[1.45,1.55])}</div>${button('Close replay','harbor-close','secondary')}</section>`;}
function freeLab(){const l=ui.lab,model=adapters[l.adapter],last=l.trials.at(-1),readiness=toolReadiness(profile(),l.adapter);return `<section class="content">${ui.labFromHarbor?button('← Return to Motion Harbor','region','back','data-id="motion"'):''}${heading('YOUR INVENTION WORKSHOP',l.coop?'Co-op Lab':'Free Lab','Change a design, compare results, and keep your inventions.',button(l.coop?'Solo lab':'Shared-device co-op','coop','secondary'))}<div class="lab-tabs" role="group" aria-label="Choose an experiment">${Object.entries(adapters).map(([id,m])=>button(m.label,'lab-adapter',l.adapter===id?'selected':'',`data-id="${id}"`)).join('')}</div>${l.coop?`<div class="coop-banner"><b>Pass the device. Rotate the jobs.</b><p>${['Designer','Builder','Tester','Explainer'].map((role,i)=>`${role}: ${esc(data.profiles[(i+l.trials.length)%data.profiles.length].name)}`).join(' · ')}</p><p>Discuss a prediction before each run. Each explorer demonstrates skills in their own profile’s missions; a team experiment gives no automatic mastery.</p></div>`:''}<div class="lab-layout"><div class="lab-main"><div class="scene-card"><div class="scene-header">${model.label}<span>Exploration · no mastery awarded</span><button class="visual-mode-toggle" data-action="toggle-visual-mode" aria-label="Toggle realistic artwork and shader rendering">${ui.visualMode==='realistic'?'📐 Schematic':'🛰 Realistic'}</button></div><div id="scene">${l.adapter==='ramp'?rampBayScene(l.input,ui.replay??last,ui.progress,l.options,!!ui.animation):scene(l.adapter,ui.progress>0?(ui.replay?.input??last?.input??l.input):l.input,ui.replay??last,ui.progress,null,l.trials.at(-2),l.options,{region:missions.find(m=>m.adapter===l.adapter)?.region||'motion',visualMode:ui.visualMode})}</div></div><div class="evidence-panel"><h2>Invention trials</h2>${chart(l.trials)}${trialTable(l.trials,l.adapter)}${l.adapter.startsWith('trait-')?traitEvidence(l.trials):timeSeries(last,l.adapter)}</div>${modelCard(l.adapter)}</div><aside class="task-panel"><p class="eyebrow">BUILD SOMETHING. LEARN SOMETHING.</p><h2>${model.label}</h2>${controls(l.adapter,l.input,!!ui.animation,l.options)}${readiness.name?`<div class="tool-readiness"><h3>${readiness.name}</h3><p>${readiness.ready?'Ready: prerequisite skills demonstrated.':readiness.reason}</p>${readiness.missing.map(id=>`<p>${byId[id].title}: ${skillState(profile().runs[id])}. ${button('Open preparation →','start','secondary',`data-id="${id}"`)}</p>`).join('')}${!readiness.ready?'<p>Demonstrate all six independent checks in each preparation mission. Standard sandbox experiments and every guided mission remain available.</p>':''}</div>`:''}${l.adapter==='ramp'?`<label class="field">Lane resistance<select id="lab-resistance" ${ui.animation||!readiness.ready?'disabled':''}><option value="0.2" ${!l.options.resistance||l.options.resistance===.2?'selected':''}>Standard · 0.20</option><option value="0.1" ${l.options.resistance===.1?'selected':''}>Lower · 0.10</option><option value="0.4" ${l.options.resistance===.4?'selected':''}>Higher · 0.40</option></select></label>`:''}${l.adapter==='energy'?`<div class="model-editor"><h3>Build the energy model</h3><label class="field">Stored energy (Wh)<input id="lab-storage" type="number" min="100" max="2000" step="100" value="${l.options.storage??800}" ${ui.animation||!readiness.ready?'disabled':''}></label><label class="field">Delivery efficiency<select id="lab-efficiency" ${ui.animation||!readiness.ready?'disabled':''}>${[.6,.8,1].map(v=>`<option value="${v}" ${v===(l.options.efficiency??.8)?'selected':''}>${v*100}%</option>`).join('')}</select></label><p>Margin = storage × efficiency − load × 10 hours. Modify a parameter, predict its effect, and inspect the ledger.</p></div>`:''}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume':'Pause'):(l.adapter==='ramp'?'Release rover':'Run experiment'),'run','primary',canRunLab(profile(),l)?'':'disabled')}${button('Reset','reset','secondary')}${!canRunLab(profile(),l)?button('Use standard lab settings','lab-defaults','secondary'):''}</div>${last?`<div class="result-card"><small>${model.output}</small><strong>${round(last.value)} ${model.outUnit}</strong></div><label class="field">Name this invention<input id="invention-name" maxlength="50" placeholder="My ${model.label.toLowerCase()}"></label>${button('Save invention ✧','save-invention','secondary full')}`:''}${l.adapter==='ramp'?'<p class="ramp-help">Drag the height handle, use its arrow keys, or use the height slider. Release the rover to record a trial. The bay is 1.45–1.55 m from the ramp exit.</p>':''}<p class="muted">Free Lab is always open. Saved inventions remain viewable; new tests with advanced settings require the preparation skills. Saved inventions and skill evidence are kept separately.</p></aside></div></section>`;}
function attemptHistory(r,m){return `<details class="attempt-history"><summary>Attempt history & adult feedback (${(r.assessmentHistory||[]).length} checks)</summary>${r.predictionNote?`<p><b>Prediction reasoning:</b> ${esc(r.predictionNote)}</p>`:''}${(r.assessmentHistory||[]).map(a=>`<article class="invention"><h3>${esc(a.category)} · ${a.correct?'correct':'revise'}${a.assisted?' · with help':' · independent'}</h3><p>${esc(a.prompt)}</p><p>${esc(a.answer)}</p>${a.coaching?`<p><b>Coaching shown:</b> ${esc(a.coaching.text)}</p>`:''}<p class="muted">${new Date(a.at).toLocaleString()} · content ${a.contentVersion} · ${a.trialIds.length+a.transferTrialIds.length} linked trials${a.retentionReview?' · retention review':''}</p></article>`).join('')||'<p>Detailed attempt records begin with this update. Previously earned evidence remains.</p>'}${r.planHistory?.length?`<h3>Investigation plans</h3>${r.planHistory.map(p=>`<article class="invention"><p>${p.correct?'Plan meets the investigation brief':'Plan needs revision'}${p.assisted?' · with help':''}</p><ul>${p.decisions.map(d=>`<li>${esc(d.question)} ${esc(d.answer||'Not chosen')}</li>`).join('')}</ul></article>`).join('')}`:''}<h3>Adult discussion notes</h3>${(r.adultFeedback||[]).map(f=>`<p><b>${esc(f.reviewer)}</b> · ${esc(f.nextStep)}<br>${esc(f.note)}</p>`).join('')}<form class="adult-feedback" data-mission="${m.id}"><label class="field">Adult name<input name="reviewer" maxlength="80" required></label><label class="field">Feedback<textarea name="note" maxlength="2000" required></textarea></label><label class="field">Next step<select name="nextStep"><option value="discuss">Discuss the evidence</option><option value="practice">Practice the idea</option><option value="extend">Try a new challenge</option></select></label><button class="secondary" type="submit">Save discussion note</button><p class="muted">Local feedback is not authenticated and does not award or remove mastery.</p></form></details>`;}
function buildOffJournal(p){return (p.buildOffRecords||[]).length?`<details class="model-card"><summary>Build-Off design comparisons (${p.buildOffRecords.length})</summary>${p.buildOffRecords.map(r=>`<article><h3>${new Date(r.at).toLocaleDateString()} · ${r.scored?'Practice challenge':'Supported preview'}</h3><p>Selected design ${r.choice+1}: lower starting height with less lane resistance for the same delivery.</p><table><caption>Saved starting-energy comparison</caption><thead><tr><th>Design</th><th>Height (m)</th><th>Resistance</th><th>Distance (m)</th><th>Energy (J)</th></tr></thead><tbody>${r.designs.map(d=>`<tr><th>${d.round+1}</th><td>${round(d.height)}</td><td>${d.resistance}</td><td>${round(d.distance)}</td><td>${round(d.energy)}</td></tr>`).join('')}</tbody></table><p>Design economy, not a conversion-efficiency measurement. No mission mastery awarded.</p></article>`).join('')}</details>`:'';}
function journal(){const p=profile(),seen=missions.filter(m=>p.runs[m.id]),dem=seen.filter(m=>['Demonstrated','Retained'].includes(skillState(p.runs[m.id])));return `<section class="content">${harborRuntimeJournal(p)}${buildOffJournal(p)}${p.climateData?climateDataHistory(p.climateData):''}${p.energyCapstone?energyCapstoneHistory(p.energyCapstone):''}${p.energyConstruction?energyConstructionHistory(p.energyConstruction):''}${p.motionData?motionDataHistory(p.motionData):''}${heading('THE FIELD JOURNAL','Small experiments. Big discoveries.',`${esc(p.name)}’s notebook · ${seen.reduce((n,m)=>n+p.runs[m.id].trials.length,0)} recorded trials`)}<div class="journal-stats"><div><strong>${achievements()}</strong><span>Discoveries made</span></div><div><strong>${dem.length}</strong><span>Skills demonstrated</span></div><div><strong>${p.inventions.length}</strong><span>Inventions saved</span></div></div><div class="journal-columns"><div><h2>Evidence & next steps</h2>${seen.length?seen.map(m=>{const r=p.runs[m.id],state=skillState(r),due=r.completedAt&&Date.now()-r.completedAt>86400000;return `<details class="journal-entry"><summary><span>${regionOf(m).icon} &nbsp;${m.title}</span>${badge(state,state==='Demonstrated'||state==='Retained'?'success':'')}</summary><div class="evidence-grid">${CATEGORIES.map(k=>`<span class="${r.evidence[k]?'earned':''}">${r.evidence[k]?'✓':'○'} ${k}</span>`).join('')}</div>${trialTable(r.trials,m.adapter,true)}${Object.entries(r.transferTrials||{}).map(([stage,trials])=>`<h3>${esc(transferPlan(m,{stage})?.title||stage)}</h3>${trialTable(trials,m.adapter,true)}`).join('')}${attemptHistory(r,m)}${r.notes?`<p><b>Explorer’s explanation (adult review):</b> ${esc(r.notes)}</p>`:''}<p>Help used: ${[...new Set((r.hintHistory||[]).map(h=>h.stage).concat(Object.keys(r.assistance).filter(k=>r.assistance[k])))].join(', ')||'none'}.</p><p class="muted">Mission completion and demonstrated understanding are separate. ${m.review}.</p>${button('Open mission','start','secondary',`data-id="${m.id}"`)}${due&&CATEGORIES.every(k=>r.evidence[k])?button('Later-session review','review','secondary',`data-id="${m.id}"`):''}</details>`;}).join(''):`<div class="empty-state">${robotSvg()}<h3>Your first page is waiting.</h3><p>Run an experiment and Pip will record the results here.</p>${button('Try Rover Rescue','start','primary','data-id="rover-rescue"')}</div>`}</div><div><h2>Shared investigations</h2>${profile().coopEvidence?.length?profile().coopEvidence.slice(-12).map(e=>`<article class="invention"><h3>${esc(byId[e.mission]?.title||e.mission)}</h3><p>Round ${e.round+1} · ${e.phase} · ${e.correct?'fits the model':'needs another look'}${e.assisted?' · supported':''}</p><p>${esc(e.answer)}</p>${button('Practice on my own','start','secondary',`data-id="${e.mission}"`)}</article>`).join(''):'<p class="empty">Individual co-op contributions will appear here.</p>'}<h2>My inventions</h2>${p.inventions.length?p.inventions.map((inv,i)=>`<article class="invention"><span>⚒</span><h3>${esc(inv.name)}</h3><p>${adapters[inv.adapter]?.label} · ${round(inv.result.value)} ${adapters[inv.adapter]?.outUnit}</p>${button('Rebuild','load-invention','secondary',`data-index="${i}"`)}</article>`).join(''):'<p class="empty">Visit Free Lab to build and save an invention.</p>'}<div class="adult-note"><h3>For grown-ups</h3><p>Six independent checks support a “Demonstrated” label. Answer-revealing help never earns independent evidence. Later-session review is offered after a day.</p><p>These are original early-access investigations, not a complete or certified K–12 curriculum. Educator review and learner playtesting remain outstanding.</p>${button('Backup & profiles','nav','secondary','data-view="settings"')}</div></div></div></section>`;}
function arcadeView(){if(ui.arcade)return arcadeGame();const modes=[['cargo','Cargo Catch','Land a supply rover in three different delivery bays.','rover-rescue','⚙'],['signal','Signal Sprint','Match the receiver’s wavelength. Timing is optional.','signal-sprint','ϟ'],['habitat','Habitat Balance','Respond to resource changes with a supported explanation.','habitat-supply','♧'],['buildoff','Build-Off','Compare three working designs and their starting-energy requirements.','rover-rescue','⚒']];return `<section class="content">${heading('THE DISCOVERY ARCADE','Play with what you know.','Untimed challenges. Unlimited retries. A new way to use an idea.')}<div class="arcade-grid">${modes.map(([id,title,desc,prereq,icon])=>{const unlocked=['Demonstrated','Retained'].includes(skillState(profile().runs[prereq]));return `<article class="arcade-card"><div class="arcade-icon">${icon}</div><h2>${title}</h2><p>${desc}</p>${badge(unlocked?'Ready to play':'Preparation available',unlocked?'success':'')}<div class="arcade-actions">${button(unlocked?'Play challenge →':'Supported preview →','arcade-start','primary',`data-id="${id}" data-scored="${unlocked}"`)}${!unlocked?button('Learn: '+byId[prereq].title,'start','text-button',`data-id="${prereq}"`):''}</div><p class="muted">Best: ${profile().arcade[id]??0} · practice scores never award science mastery</p></article>`;}).join('')}</div></section>`;}
function buildOffComparison(a){const comparison=compareBuildOff(a.designs);return `<section class="content">${button('← Arcade','arcade-exit','back')}${heading('BUILD-OFF / COMPARE DESIGNS','Same delivery. Different energy requirements.','All three tested designs stop in the same 1 m bay with the same 2 kg cart.')}<div class="table-scroll"><table><caption>Accepted delivery designs</caption><thead><tr><th>Design</th><th>Ramp height (m)</th><th>Rolling resistance</th><th>Stopping distance (m)</th><th>Starting energy (J)</th></tr></thead><tbody>${comparison.designs.map(d=>`<tr><th>${d.round+1}</th><td>${round(d.height)}</td><td>${d.resistance}</td><td>${round(d.distance)}</td><td>${round(d.energy)}</td></tr>`).join('')}</tbody></table></div><p>Starting gravitational energy = mass × gravity × ramp height. The ramp is ideal and lossless. The stopping lane transfers all that energy to the surroundings by the time the cart stops.</p><h2>Which working design needs the least starting energy?</h2>${comparison.designs.map(d=>button('Design '+(d.round+1),'buildoff-choice',`choice ${a.designChoice===d.round?'selected':''}`,`data-value="${d.round}" aria-pressed="${a.designChoice===d.round}"`)).join('')}<h2>Why does it need less?</h2>${['Less rolling resistance allows the same stopping distance from a lower starting height.','Its energy disappears instead of transferring to the surroundings.','It turns more than 100% of its starting energy into useful energy.'].map((text,i)=>button(text,'buildoff-reason',`choice ${a.designReason===i?'selected':''}`,`data-value="${i}" aria-pressed="${a.designReason===i}"`)).join('')}${button('Check my comparison','buildoff-check','primary',Number.isInteger(a.designChoice)&&Number.isInteger(a.designReason)?'':'disabled')}${a.comparisonFeedback?`<p role="status" class="feedback">${esc(a.comparisonFeedback)}</p>`:''}<p class="muted">This compares energy required for a fixed delivery task. It is not a measured conversion-efficiency percentage, and does not include construction cost, real wheel losses or safety. Arcade points never award science mastery.</p></section>`;}
function arcadeGame(){const a=ui.arcade;if(a.id==='buildoff'&&a.round===3&&!a.comparisonComplete)return buildOffComparison(a);let adapter=a.id==='signal'?'wave':a.id==='habitat'?'habitat':'ramp',target=a.id==='signal'?[5,2,10][a.round%3]:a.id==='buildoff'?1:[1,2,1.5][a.round%3];const done=a.round>=3;return `<section class="content">${button('← Arcade','arcade-exit','back')}${heading(a.scored?'PRACTICE CHALLENGE':'SUPPORTED PREVIEW',({cargo:'Cargo Catch',signal:'Signal Sprint',habitat:'Habitat Balance',buildoff:'Build-Off'})[a.id],`Round ${Math.min(3,a.round+1)} of 3 · ${a.score} points · no timer`)}${done?`<div class="celebration"><div class="completion-icon">✧</div><h2>Challenge complete!</h2><p>${a.score} points ${a.scored?'saved to this explorer':'in supported preview'}.</p>${a.id==='buildoff'?'<p>Three working designs and your energy comparison are saved to this explorer’s journal.</p>':''}${button('Return to arcade','arcade-exit','primary')}</div>`:`<div class="lab-layout"><div class="scene-card"><div id="scene">${scene(adapter,a.input,a.result,a.result?1:0,adapter==='ramp'?[target-.05,target+.05]:null)}</div>${a.result?`<p class="scene-caption">Result: ${round(a.result.value)} ${adapters[adapter].outUnit}</p>`:''}</div><aside class="task-panel"><h2>${a.id==='habitat'?`Supply ${[4,8,6][a.round]} animals`:`Target: ${target} ${adapters[adapter].outUnit}`}</h2><p>${a.id==='buildoff'?`Design ${a.round+1}: use resistance ${[.2,.4,.1][a.round]}. Land at the same bay with a different ramp.`:a.id==='habitat'?'Each animal needs 5 units of food each day. Choose the exact food budget.':'Adjust one setting and test your design.'}</p>${controls(adapter,a.input)}${button('Test my design','arcade-test','primary full')}${a.feedback?`<div class="feedback ${a.passed?'good':'try'}">${esc(a.feedback)}</div>`:''}${a.passed?button('Next round →','arcade-next','secondary full'):''}</aside></div>`}</section>`;}
function placementView(){const p=profile().placement,suggestion=p&&placementSuggestion(p);if(!p)return '';if(p.status!=='active')return `<section class="content">${heading('OPTIONAL STARTING POINT',p.status==='skipped'?'Choose your own adventure.':'A place to begin.','This activity suggests a starting mission. It does not award mastery or unlock advanced tools.')}<p>${suggestion?suggestion.reason:'You can explore any guided mission or return to this activity later.'}</p>${suggestion?button('Try '+byId[suggestion.mission].title,'start','primary',`data-id="${suggestion.mission}"`):button('Explore the islands','nav','primary','data-view="explore"')}${button('Choose a learning pathway','nav','secondary','data-view="courses"')}${button('Try these questions again','placement-restart','text-button')}</section>`;const index=p.responses.length,item=placementItems[index],order=[0,1,2].map(i=>(i+index+1)%3);return `<section class="content">${heading('OPTIONAL STARTING POINT',`Question ${index+1} of ${placementItems.length}`,'No timer. No grade. You can skip and choose any mission.')}<div class="task-panel"><h2>${item.prompt}</h2>${button('Read question and choices aloud','placement-narrate','secondary')}${button('Stop reading','stop-reading','text-button')}<div role="group" aria-label="Choose one response">${order.map(i=>button(item.options[i],'placement-choice',`choice ${p.choice===i?'selected':''}`,`data-value="${i}" aria-pressed="${p.choice===i}"`)).join('')}</div>${button(index===placementItems.length-1?'See my suggestion':'Next question','placement-next','primary',p.choice===null?'disabled':'')}${button('Skip this activity','placement-skip','text-button')}</div><p class="muted">Responses are saved on this device for this explorer. Reading preferences are separate from science readiness. You can leave and resume later.</p></section>`;}
function settings(){const p=profile();return `<section class="content settings">${teachPathEntry()}${heading('MAKE YOURSELF AT HOME','Explorers & settings','Profiles and progress stay in this browser. No account or personal information needed.')}<div class="settings-grid"><section class="settings-panel"><h2>Choose an explorer</h2><div class="profiles">${data.profiles.map(x=>`<button class="explorer ${x.id===p.id?'selected':''}" data-action="profile" data-id="${x.id}" aria-pressed="${x.id===p.id}"><span>${esc(x.avatar)}</span><b>${esc(x.name)}</b>${x.id===p.id?'<small>Playing now</small>':''}</button>`).join('')}</div><form id="new-profile"><label class="field">Explorer nickname<input id="profile-name" maxlength="30" required placeholder="e.g. River" autocomplete="off"></label><label class="field">Explorer<select id="profile-avatar"><option>🧑🏽‍🚀</option><option>👩🏿‍🔬</option><option>👨🏻‍🔬</option><option>👩🏽‍🚀</option><option>🧑🏼‍🔬</option><option>🤖</option></select></label><button class="secondary" type="submit" ${data.profiles.length>=12?'disabled':''}>Add explorer</button></form>${data.profiles.length>1?button('Delete this explorer’s local progress','delete-profile','danger text-button'):''}</section><section class="settings-panel"><h2>Comfort & reading</h2><p>Saved separately for ${esc(p.name)}.</p><label class="toggle"><input id="picture-support" type="checkbox" ${reading().pictures?'checked':''}> Picture cues where available</label><label class="field">Read-aloud speed<select id="reading-rate">${[[.7,'Slower'],[.9,'Gentle'],[1.1,'Quicker']].map(([v,label])=>`<option value="${v}" ${reading().rate===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Learning pathway<select id="band">${['All explorers','K–2','3–5','6–8','9–12'].map(b=>`<option ${reading().band===b?'selected':''}>${b}</option>`).join('')}</select></label><p class="muted">A guide for where to begin; all investigations stay available.</p><label class="toggle"><input id="large-text" type="checkbox" ${reading().large?'checked':''}> Larger text</label><label class="toggle"><input id="reduced-motion" type="checkbox" ${reading().reduced?'checked':''}> Reduce animation</label><label class="toggle"><input id="technical-theme" type="checkbox" ${reading().technical?'checked':''}> Night / technical theme</label>${button('Read a sample aloud','sample-narration','secondary')}<p class="muted">Read-aloud uses your device’s available voice. Every spoken message is also written on screen. English content.</p><h3>Find a starting point</h3><p>Four optional questions suggest a mission. You can skip them; they never award mastery.</p>${button(profile().placement?.status==='active'?'Resume starting-point activity':'Find my starting point','placement-open','secondary')}<h3>Readiness bridge</h3><p>New to experiments? Compare two pushes, then learn what makes a fair test.</p>${button('Start with First Move','start','secondary','data-id="first-move"')}</section><section class="settings-panel"><h2>Keep your discoveries</h2><p><a href="./rooms/">Private online room setup ↗</a> · service deployment pending</p><p><a href="./sync/">Device sync setup ↗</a> · cloud service deployment pending</p><p>Export a backup to move explorers between devices. Import merges by explorer ID and keeps a separate imported copy if progress differs.</p><div class="run-buttons">${button('Export backup','export','primary')}<label class="button secondary">Import backup<input id="import-save" type="file" accept="application/json,.json" hidden></label></div><p class="muted">Storage: ${storageMode}. ${navigator.onLine?'Online':'Offline'}. Export regularly if this device clears browser data.</p>${button('Export recovery archives','export-recovery','text-button')}<h3>About this release</h3><p><a href="./coverage/">Curriculum coverage and review ledger ↗</a></p><p><a href="./author/">Content Studio: author and review investigations ↗</a></p><p>${missions.length} playable investigations across six regions, with guided missions, a free lab and four arcade challenges.</p><p>Local shared-device co-op is in Build. Online co-op and account sync are not included. Device export/import is available.</p><p>Original curriculum in early access. No claims of complete standards coverage or proven learning outcomes.</p><a href="https://chiokebuckley-art.github.io/engineering-quest/" target="_blank" rel="noopener">Engineering Quest ↗</a> · <a href="https://chiokebuckley-art.github.io/wordraiders/" target="_blank" rel="noopener">Word Raiders ↗</a></section></div></section>`;}
