function render(){const teachWorld=inTeachWorld();const oldHarbor=$('#harbor-walk-canvas-container'),oldAdventure=$('#adventure-3d-canvas-container');const is3D=teachWorld||ui.view==='harbor-walk'||ui.view==='adventure-3d';document.body.classList.toggle('is-immersive-3d',is3D);document.body.classList.toggle('large-text',!!reading().large);document.body.classList.toggle('technical',!!reading().technical);document.body.classList.toggle('reduced',!!reading().reduced);let views={'teach-path':()=>teachPathView(profile()),explore:mapView,dictionary:()=>dictionaryView({met:wordsMet(),query:ui.dictQuery}),cinema:()=>{const doc=cinemaById(ui.cinema.activeId);return cinemaView({...ui.cinema,unlocked:filmUnlocked(doc),formulas:formulasTaught(doc),met:wordsMet(),lockWords:filmWords(doc),missionTitle:byId[doc.missionId]?.title});},workshop:workshopView,coop:coopView,courses:coursesView,region:regionView,mission:missionView,math:()=>mathBridgeView(ui.mathId,profile().mathBridges[ui.mathId]),capstone:routeCapstoneView,placement:placementView,'climate-data':()=>climateDataView(profile().climateData??=createClimateData()),'energy-capstone':()=>energyCapstoneView(profile().energyCapstone??=createEnergyCapstone()),'energy-model':()=>energyConstructionView(profile().energyConstruction??=createEnergyConstruction()),'motion-data':()=>motionDataView(profile().motionData??=createMotionData()),lab:freeLab,journal,arcade:arcadeView,settings,'harbor-walk':()=>harborWalkView(profile(),ui.harborWalk??=createHarborWalkState()),'adventure-3d':()=>adventure3DView(ui.activeAdventure||'motion',profile(),(ui.adventures??={})[ui.activeAdventure||'motion']??=createAdventureState(ui.activeAdventure||'motion'))};let body=(views[ui.view]||mapView)();if(teachWorld)body=fieldTabletFrame(body,{collapsed:!!ui.teachCollapsed});app.innerHTML=shell(body)+(ui.word&&glossary[ui.word]?wordLayer(ui.word,{met:true,clip:ui.clip}):'');if((teachWorld||ui.view==='harbor-walk')&&oldHarbor&&harborWalkInstance){const replacement=$('#harbor-walk-canvas-container');oldHarbor.className=replacement.className;replacement.replaceWith(oldHarbor);harborWalkInstance.resize?.();}if(ui.view==='adventure-3d'&&oldAdventure&&adventure3DInstance){$('#adventure-3d-canvas-container')?.replaceWith(oldAdventure);adventure3DInstance.resize?.();}syncHarborClock();if(ui.view==='cinema')attachCinemaVideoListeners();if(teachWorld||ui.view==='harbor-walk')attachHarborWalk();else stopHarborWalk();if(ui.view==='adventure-3d')attachAdventure3D();else stopAdventure3D();}
let harborClock=null;
function stopHarborClock(){if(harborClock)cancelAnimationFrame(harborClock.frame);harborClock=null;}
function syncHarborClock(){
 const active=data&&ui.view==='region'&&ui.region==='motion'&&!document.hidden&&!saveError&&!ensureHarborRuntime(profile()).settings.paused;
 if(!active){stopHarborClock();return;}
 if(harborClock?.profile===data.active)return;
 stopHarborClock();const clock={profile:data.active,frame:0,ticker:createFixedTicker(),paintAt:profile().harborRuntime.ticks,saveAt:profile().harborRuntime.ticks};harborClock=clock;
 function frame(now){if(harborClock!==clock)return;if(document.hidden||saveError||data.active!==clock.profile||ui.view!=='region'||ui.region!=='motion'){stopHarborClock();return;}
  let changed=false;clock.ticker.frame(now,()=>{stepHarbor(profile());changed=true;});
  if(changed){const ticks=profile().harborRuntime.ticks;if(ticks-clock.paintAt>=5){clock.paintAt=ticks;updateHarborRuntimeView(profile(),ui.harborSite,reading().reduced||matchMedia('(prefers-reduced-motion: reduce)').matches);}if(ticks-clock.saveAt>=50){clock.saveAt=ticks;save('harbor-runtime');}}
  clock.frame=requestAnimationFrame(frame);
 }
 clock.frame=requestAnimationFrame(frame);
}
document.addEventListener('visibilitychange',()=>{stopHarborClock();if(document.hidden){if(data?.profiles&&profile().harborRuntime&&!saveError)save('harbor-visibility-pause');}else syncHarborClock();});
window.addEventListener('pagehide',()=>{stopHarborClock();if(data?.profiles&&profile().harborRuntime&&!saveError)save('harbor-page-pause');});
function stopAnimation(){ui.rampDrag=null;if(ui.animation)cancelAnimationFrame(ui.animation.frame);ui.animation=null;ui.paused=false;ui.replay=null;}
let cinemaTimer=null;
function stopCinema(){
 if(cinemaTimer){cancelAnimationFrame(cinemaTimer);cinemaTimer=null;}
 const v=$('#cinema-video');
 if(v){try{v.pause();}catch(e){}}
 if(ui.cinema)ui.cinema.isPlaying=false;
}

function syncCinemaControls(){
 const v=$('#cinema-video');
 const doc=cinemaById(ui.cinema.activeId);
 const dur=v&&v.duration&&isFinite(v.duration)?v.duration:doc.duration;
 const playBtn=$('#cinema-play-btn');
 if(playBtn){
  playBtn.textContent=ui.cinema.isPlaying?'⏸ Pause':'▶ Play';
  playBtn.setAttribute('aria-label',ui.cinema.isPlaying?'Pause':'Play');
 }
 const bigPlay=$('.cinema-big-play');
 if(bigPlay)bigPlay.style.display=ui.cinema.isPlaying?'none':'block';
 const muteBtn=$('#cinema-mute-btn');
 if(muteBtn){
  muteBtn.textContent=ui.cinema.muted?'🔇 Muted':'🔊 Voiceover';
  muteBtn.setAttribute('aria-label',ui.cinema.muted?'Unmute voiceover':'Mute voiceover');
 }
 updateCinemaScreen();
}

function attachCinemaVideoListeners(){
 const v=$('#cinema-video');
 if(!v||v._boundEvents)return;
 v._boundEvents=true;
 v.addEventListener('timeupdate',()=>{
  if(!v.paused){
   ui.cinema.currentTime=v.currentTime;
   updateCinemaScreen();
  }
 });
 v.addEventListener('ended',()=>{
  ui.cinema.isPlaying=false;
  stopCinema();
  syncCinemaControls();
 });
 v.addEventListener('play',()=>{
  if(!ui.cinema.isPlaying){
   ui.cinema.isPlaying=true;
   syncCinemaControls();
  }
 });
 v.addEventListener('pause',()=>{
  if(ui.cinema.isPlaying){
   ui.cinema.isPlaying=false;
   syncCinemaControls();
  }
 });
}

function toggleCinemaPlayback(){
 const v=$('#cinema-video');
 const doc=cinemaById(ui.cinema.activeId);
 const dur=v&&v.duration&&isFinite(v.duration)?v.duration:doc.duration;
 if(ui.cinema.isPlaying){
  stopCinema();
  syncCinemaControls();
 }else{
  if(ui.cinema.currentTime>=dur)ui.cinema.currentTime=0;
  ui.cinema.isPlaying=true;
  if(v){
   v.muted=!!ui.cinema.muted;
   v.playbackRate=ui.cinema.speed||1;
   if(Math.abs(v.currentTime-ui.cinema.currentTime)>0.3)v.currentTime=ui.cinema.currentTime;
   const playPromise=v.play();
   if(playPromise!==undefined){
    playPromise.catch(()=>{
     if(!v.muted){
      v.muted=true;
      ui.cinema.muted=true;
      v.play().catch(()=>{});
     }
    });
   }
  }
  let lastTimestamp=performance.now();
  function tick(now){
   if(!ui.cinema.isPlaying)return;
   const delta=(now-lastTimestamp)/1000;
   lastTimestamp=now;
   if(v&&!v.paused&&!v.ended){
    ui.cinema.currentTime=v.currentTime;
   }else if(!v){
    ui.cinema.currentTime+=delta*(ui.cinema.speed||1);
   }
   if(ui.cinema.currentTime>=dur||(v&&v.ended)){
    ui.cinema.currentTime=dur;
    stopCinema();
    syncCinemaControls();
    return;
   }
   updateCinemaScreen();
   cinemaTimer=requestAnimationFrame(tick);
  }
  cinemaTimer=requestAnimationFrame(tick);
  syncCinemaControls();
 }
}

function seekCinema(time){
 const doc=cinemaById(ui.cinema.activeId);
 const v=$('#cinema-video');
 const dur=v&&v.duration&&isFinite(v.duration)?v.duration:doc.duration;
 ui.cinema.currentTime=Math.max(0,Math.min(dur,time));
 if(v){try{v.currentTime=ui.cinema.currentTime;}catch(e){}}
 updateCinemaScreen();
}

function updateCinemaScreen(){
 const doc=cinemaById(ui.cinema.activeId);
 const v=$('#cinema-video');
 const dur=v&&v.duration&&isFinite(v.duration)?v.duration:doc.duration;
 const t=ui.cinema.currentTime;
 const progress=dur>0?Math.min(1,t/dur):0;

 const sim=$('#cinema-sim-overlay');
 if(sim)sim.innerHTML=cinemaOverlayScene(doc,t,progress,{formulas:formulasTaught(doc)});

 const captionText=$('#cinema-caption-text');
 const captionBox=$('#cinema-caption-box');
 const showCaptions=ui.cinema.showCaptions!==false;
 const c=showCaptions?activeCaption(doc,t):null;
 if(captionText)captionText.textContent=c?c.text:'';
 if(captionBox){
  captionBox.classList.toggle('active',!!c);
  captionBox.style.display=(c&&showCaptions)?'flex':'none';
 }

 const chapterTag=$('#cinema-chapter-tag');
 if(chapterTag){
  const ch=activeChapter(doc,t);
  chapterTag.textContent=ch?ch.title:'';
 }

 const scrubber=$('#cinema-scrubber');
 if(scrubber){
  scrubber.value=t;
  scrubber.max=dur;
 }
 const scrubberProgress=$('#cinema-scrubber-progress');
 if(scrubberProgress)scrubberProgress.style.width=`${progress*100}%`;

 const timeDisplay=$('#cinema-time-display');
 if(timeDisplay)timeDisplay.textContent=`${formatTime(t)} / ${formatTime(dur)}`;
}
function animate(result,adapter,target=null,onComplete){stopAnimation();ui.replay=result;if(reading().reduced||matchMedia('(prefers-reduced-motion: reduce)').matches){ui.progress=1;onComplete?.();render();return;}ui.animation={elapsed:0,last:performance.now(),frame:0};const duration=adapter==='plant'||adapter==='energy'?3500:Math.min(5500,Math.max(2000,result.duration*700));render();function frame(now){if(!ui.animation)return;const a=ui.animation;if(!ui.paused)a.elapsed+=Math.min(100,now-a.last);a.last=now;ui.progress=Math.min(1,a.elapsed/duration);const targetEl=$('#scene');if(targetEl)targetEl.innerHTML=ui.view==='lab'&&adapter==='ramp'?rampBayScene(result.input,result,ui.progress,result.options||{},true):scene(adapter,result.input,result,ui.progress,target,null,result.options||{},ui.view==='mission'?{...currentMission(),visualMode:ui.visualMode}:{region:missions.find(m=>m.adapter===adapter)?.region||'motion',visualMode:ui.visualMode});if(ui.progress<1)a.frame=requestAnimationFrame(frame);else{ui.animation=null;onComplete?.();render();}}ui.animation.frame=requestAnimationFrame(frame);}
function runExperiment(){if(ui.animation){ui.paused=!ui.paused;render();return;}const lab=ui.view==='lab',m=lab?null:currentMission(),r=lab?ui.lab:currentRun(),adapter=lab?r.adapter:m.adapter;const transfer=lab?null:transferPlan(m,r);if(!lab&&((r.stage!=='test'&&!transfer)||(adapter==='energy'&&!r.energyModel)))return;if(lab)validateLabOptions(profile(),adapter,r.options);const result={...simulate(adapter,r.input,lab?r.options:(transfer?.options||{})),id:crypto.randomUUID(),at:Date.now()};if(transfer){r.transferTrials??={};r.transferTrials[r.stage]??=[];r.transferTrials[r.stage].push(result);}else{r.trials.push(result);if(!lab)r.trialIds.push(result.id);}if(lab)ui.lab.trials=r.trials;save(transfer?'transfer-trial':'trial',{stage:r.stage,configuration:{input:r.input,options:lab?r.options:(transfer?.options||{})},measurements:result,hintFlags:lab?{}:r.assistance});animate(result,adapter,transfer?.target??m?.target);}
function setInput(value,keepDrag=false){const a=ui.arcade;const holder=ui.view==='arcade'?a:ui.view==='lab'?ui.lab:currentRun();const id=ui.view==='arcade'?(a.id==='signal'?'wave':a.id==='habitat'?'habitat':'ramp'):ui.view==='lab'?ui.lab.adapter:currentMission().adapter;const m=adapters[id];holder.input=round(Math.max(m.min,Math.min(m.max,value)),6);if(a){a.passed=false;a.feedback='';a.result=null;}ui.progress=0;ui.replay=null;const out=$('#input-output');if(out){const simple=ui.view==='mission'?earlyControl(currentMission(),holder.input):null;out.textContent=simple?simple.value+' ('+holder.input+' '+m.unit+')':holder.input+' '+m.unit;}const slider=$('#experiment-input');if(slider)slider.value=holder.input;if(ui.view==='lab'&&id==='ramp'){if(keepDrag&&ui.rampDrag){$('.ramp-scene-art').innerHTML=scene('ramp',holder.input,null,0,[1.45,1.55],null,holder.options);const handle=ui.rampDrag.element;handle.style.top=rampHandleTop(holder.input)+'%';handle.setAttribute('aria-valuenow',holder.input);handle.setAttribute('aria-valuetext',holder.input.toFixed(2)+' metres');}else $('#scene').innerHTML=rampBayScene(holder.input,null,0,holder.options);}else $('#scene').innerHTML=scene(id,holder.input,null,0,ui.view==='mission'?(transferPlan(currentMission(),currentRun())?.target??currentMission().target):null,null,ui.view==='mission'?(transferPlan(currentMission(),currentRun())?.options||{}):holder.options||{},ui.view==='mission'?{...currentMission(),visualMode:ui.visualMode}:{region:missions.find(m=>m.adapter===id)?.region||'motion',visualMode:ui.visualMode});save('configuration',{input:holder.input});}
function moveNext(){const r=currentRun();if((currentMission().id==='restore-route'||currentMission().capstone)&&r.stage==='transfer2'&&checkpoint(r).feedback?.ok&&!r.capstone?.complete){r.capstone??=createRouteCapstone(currentMission().capstone??'harbor');save('capstone-start');goto('capstone');return;}advanceRun(r);const gained=reconcileWorld(profile());if(gained.length){ui.harborFresh={profile:data.active,ids:worldUpgrades.filter(w=>w.region==='motion'&&gained.includes(w.name)).map(w=>w.id)};const site=harborSites.find(s=>ui.harborFresh.ids.includes(s.upgrade));if(site)ui.harborSite=site.id;notify('Restored: '+gained.join(', '));}beginTransfer(r,currentMission());if(transferPlan(currentMission(),r)){ui.progress=0;ui.replay=null;}ui.choice=null;ui.feedback=null;save('step',{stage:r.stage,evidence:r.evidence});render();document.querySelector('.task-panel h2')?.setAttribute('tabindex','-1');document.querySelector('.task-panel h2')?.focus();}
function checkAnswer(){const m=currentMission(),r=currentRun();if(r.stage==='build'&&supportsFairSetup(m)&&!fairSetupReady(fairSetupFor(m,r))){ui.feedback={ok:false,text:'A fair setup changes height only. Choose two different heights and keep the lane fixed.'};storeFeedback(r,ui.feedback);save('fair-setup-blocked');render();return;}if(r.stage==='build'&&needsPlan(m)){const plan=planSnapshot(r);r.planHistory??=[];r.planHistory.push({...plan,at:Date.now(),assisted:!!r.assistance.build});if(!plan.correct){ui.feedback={ok:false,text:plan.feedback};storeFeedback(r,ui.feedback);save('investigation-plan-check',{plan});render();return;}}if(!transferSatisfied(m,r)){notify('Test a design that meets the transfer brief before explaining it.');return;}const q=questionFor(m,r),coaching=misconceptionFeedback(m,r,q,ui.choice);if(coaching)revealItem(r,m,q);if(itemWasRevealed(r,m,q))r.assistance[r.stage]=true;const attempt=recordAttempt(r,m,q,ui.choice),ok=attempt.correct;const category={build:'fair',compare:'interpret'}[r.stage]||r.stage;if(r.reviewing){if(ok&&!r.assistance[r.stage]){r.retainedAt=Date.now();r.reviewFailed=false;}else if(!ok){r.reviewFailed=true;}}else recordCheck(r,category,ok,!!r.assistance[r.stage]);ui.feedback=ok?{ok:true,text:r.assistance[r.stage]?'That fits the evidence. This supported check is saved. A different, unrevealed question is needed for independent evidence.':'That fits the evidence. Your independent check is recorded.'}:{ok:false,text:coaching?.text||'Take another look at what changed and what stayed the same. Compare the measurements, then try again.'};if(coaching)attempt.coaching={text:coaching.text,specific:coaching.specific};storeFeedback(r,ui.feedback);save('assessment',{fairSetup:r.stage==='build'&&supportsFairSetup(m)?structuredClone(fairSetupFor(m,r)):null,attemptId:attempt.id,contentVersion:m.version,model:m.adapter,category,correct:ok,assisted:!!r.assistance[r.stage],selected:ui.choice,coaching:attempt.coaching||null,item:{stage:r.stage,variant:r.attempts[r.stage]||0,itemId:q.itemId||null,contextId:q.contextId||null,prompt:q.prompt,options:q.options},trialIds:(r.compareSelection||[]).slice(),transferTrialIds:transferTrials(r).map(t=>t.id),evidence:r.evidence});render();}
function narrate(text){if(!('speechSynthesis'in window)){notify('Read-aloud is unavailable on this device. All instructions remain on screen.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=reading().rate;utterance.onerror=()=>notify('The voice could not start. You can use the written instructions.');speechSynthesis.speak(utterance);}
