app.addEventListener('change',async e=>{const id=e.target.id;try{if(e.target.dataset.action==='cinema-speed'){ui.cinema.speed=Number(e.target.value);const v=$('#cinema-video');if(v)v.playbackRate=ui.cinema.speed;return;}if(e.target.dataset.harborSetting){setHarborSetting(profile(),e.target.dataset.harborSetting,Number(e.target.value));await save('harbor-setting');updateHarborRuntimeView(profile(),ui.harborSite,reading().reduced);return;}if(e.target.dataset.climate){editClimateData(profile().climateData,e.target.dataset.climate,e.target.value);await save('climate-data-draft');return;}if(e.target.dataset.energyCap){editEnergyCapstone(profile().energyCapstone,e.target.dataset.energyCap,e.target.value);await save('energy-capstone-draft');return;}if(e.target.dataset.energyModel){editEnergyConstruction(profile().energyConstruction,e.target.dataset.energyModel,e.target.value);await save('energy-construction-draft');return;}if(e.target.dataset.motionField){editMotionData(profile().motionData,e.target.dataset.motionField,e.target.value);await save('motion-data-draft');return;}if(e.target.dataset.investigation){const r=currentRun();if(r.stage!=='build'||!needsPlan(currentMission()))return;choosePlan(r,e.target.dataset.investigation,e.target.value===''?null:Number(e.target.value));ui.feedback=null;checkpoint(r).feedback=null;const field=e.target.dataset.investigation;await save('investigation-plan-choice');render();document.querySelector(`[data-investigation="${field}"]`)?.focus();return;}if(e.target.dataset.placement){if(e.target.value)placeDecoration(profile(),e.target.value,e.target.dataset.placement);else delete profile().world.placements[e.target.dataset.placement];await save('workshop-placement');render();}if(id.startsWith('energy-')){const r=currentRun();r.energyDraft??={};r.energyDraft[id.slice(7)]=e.target.value;r.energyModel=false;save('energy-model-edit');render();}if(id==='picture-support'){setReading(profile(),'pictures',e.target.checked);await save('reading-settings');render();}if(id==='reading-rate'){setReading(profile(),'rate',Number(e.target.value));await save('reading-settings');}if(['large-text','reduced-motion','technical-theme'].includes(id)){setReading(profile(),{'large-text':'large','reduced-motion':'reduced','technical-theme':'technical'}[id],e.target.checked);save('settings');render();}if(id==='band'){setReading(profile(),'band',e.target.value);save('settings');const next=missions.find(m=>m.band===e.target.value);if(next){data.lastMission=next.id;profile().lastMission=next.id;notify('Suggested starting point: '+next.title+'. All missions remain available.');}}if(id==='lab-resistance'){changeLabOption(profile(),ui.lab,'resistance',Number(e.target.value));ui.progress=0;}if(id==='lab-efficiency')changeLabOption(profile(),ui.lab,'efficiency',Number(e.target.value));if(id==='lab-storage'){changeLabOption(profile(),ui.lab,'storage',Number(e.target.value));}if(id==='import-save'){const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error('Backup is too large. Maximum 8 MB.');const imported=validateSharedSave(validateSave(JSON.parse(await file.text())));for(const p of imported.profiles){for(const [key,r]of Object.entries(p.runs)){if(!byId[key]||r.mission!==key)throw Error('Unknown mission in backup.');simulate(byId[key].adapter,r.input);for(const t of r.trials)if(!adapters[t.model])throw Error('Unknown model in backup.');}}const incoming=[];const remap=new Map();for(const p of imported.profiles){const existing=data.profiles.find(x=>x.id===p.id);if(!existing)incoming.push(p);else if(JSON.stringify(existing)!==JSON.stringify(p)){const clone=structuredClone(p);clone.id=crypto.randomUUID();clone.name=(p.name+' (imported)').slice(0,30);remap.set(p.id,clone.id);incoming.push(clone);}}if(data.profiles.length+incoming.length>12)throw Error('Import would exceed 12 explorers. Export and remove an unused local profile first.');const {merged,events}=mergeSharedSave(data,imported,remap,incoming);await replaceSaveWithEvents(merged,events);data=merged;await save('import');render();notify('Backup imported. Existing discoveries were preserved.');}}catch(error){notify('Could not import or change this setting: '+error.message);}});
app.addEventListener('submit',async e=>{if(e.target.id==='energy-model-form'){e.preventDefault();return;}if(e.target.id==='motion-data-form'){e.preventDefault();try{const s=profile().motionData;for(const el of e.target.querySelectorAll('[data-motion-field]'))editMotionData(s,el.dataset.motionField,el.value);const record=checkMotionData(s);await save('motion-data-check',{record});render();}catch(error){notify(error.message);}return;}if(e.target.matches('.adult-feedback')){e.preventDefault();try{const f=e.target,r=profile().runs[f.dataset.mission],review=addAdultFeedback(r,{reviewer:f.elements.reviewer.value,note:f.elements.note.value,nextStep:f.elements.nextStep.value});await save('adult-feedback',{mission:f.dataset.mission,review});render();notify('Discussion note saved.');}catch(error){notify(error.message);}return;}if(e.target.id==='coop-setup'){e.preventDefault();try{const roster=[...document.querySelectorAll('[name=coop-player]:checked')].map(el=>el.value),session=createCoopSession(roster,byId[$('#coop-mission').value],data.profiles);data.coopSessions??=[];data.coopSessions.push(session);data.coopActive=session.id;await save('coop-created',{session:session.id,roster});render();}catch(error){notify(error.message);}return;}if(e.target.id!=='new-profile')return;e.preventDefault();let name=$('#profile-name').value.trim();if(!name||data.profiles.length>=12)return;const p=makeProfile(name,$('#profile-avatar').value);ensureTeachPath(p,true);data.profiles.push(p);data.active=p.id;data.lastMission=null;stopHarborWalk();stopAdventure3D();ui.harborWalk=null;ui.adventures={};await save('profile-created');render();notify('Welcome, '+p.name+'!');});
window.addEventListener('online',()=>{if(data)render();});window.addEventListener('offline',()=>{if(data)render();});
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function showRecovery(error){app.innerHTML=`<main class="content recovery"><h1>Your discoveries are protected.</h1><p>This browser’s saved data could not be opened. Nothing has been overwritten.</p><p>${esc(error.message)}</p><button id="download-recovery" class="primary">Download original save for recovery</button><label class="button secondary">Restore a valid backup<input id="recovery-import" type="file" accept="application/json,.json" hidden></label><button id="fresh-save" class="secondary">Archive the original and start fresh</button><p class="muted">Starting fresh preserves a recovery copy in this browser. Download it first if browser storage may be cleared.</p><div id="recovery-error" role="status"></div></main>`;
$('#download-recovery').onclick=async()=>{try{downloadJSON(await recoveryExport(),'science-quest-recovery.json');}catch(e){$('#recovery-error').textContent=e.message;}};
$('#fresh-save').onclick=async()=>{try{await archiveUnreadableSave();await init();}catch(e){$('#recovery-error').textContent='Could not preserve the original, so a new save was not started. '+e.message;}};
$('#recovery-import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>8e6)throw Error('Backup exceeds 8 MB.');const incoming=validateSharedSave(validateSave(JSON.parse(await file.text())));for(const p of incoming.profiles)for(const r of Object.values(p.runs))migrateRun(r);const events=incoming.events||[];if(!Array.isArray(events)||events.some(e=>!e?.id||!e.profile))throw Error('Invalid evidence events.');await archiveUnreadableSave();await replaceSaveWithEvents(incoming,events);await init();}catch(e){$('#recovery-error').textContent=e.message;}};
}
async function init(){try{storageMode=await openStore();data=await loadSave();if(data){validateSharedSave(validateSave(data));for(const p of data.profiles)for(const r of Object.values(p.runs))migrateRun(r);}}catch(error){data=null;showRecovery(error);return;}if(!data){const p=makeProfile();ensureTeachPath(p,true);data={version:1,profiles:[p],active:p.id,lastMission:null,settings:{band:'All explorers',large:false,reduced:false,technical:false}};await save('first-visit');}data.settings??={};for(const p of data.profiles){reconcileWorld(p);readingPreferences(p,data.settings);ensureTeachPath(p);}if(profile().teachPath?.enabled){ui.view='teach-path';profile().teachPath.unit=nextTeachUnit(profile()).id;}render();const requested=new URLSearchParams(location.search).get('mission');if(requested&&byId[requested]){ensureTeachPath(profile()).enabled=false;startMission(requested);}else if(new URLSearchParams(location.search).get('activity')==='climate-data'){profile().climateData??=createClimateData();goto('climate-data');}else if(new URLSearchParams(location.search).get('activity')==='energy-capstone'){profile().energyCapstone??=createEnergyCapstone();goto('energy-capstone');}else if(new URLSearchParams(location.search).get('activity')==='energy-model'){profile().energyConstruction??=createEnergyConstruction();goto('energy-model');}else if(new URLSearchParams(location.search).get('activity')==='motion-data'){profile().motionData??=createMotionData();goto('motion-data');}else if(new URLSearchParams(location.search).get('view')==='harbor-walk'||new URLSearchParams(location.search).get('activity')==='harbor-walk'){goto('harbor-walk');}else if(new URLSearchParams(location.search).get('view')==='adventure-3d'||new URLSearchParams(location.search).get('activity')==='adventure-3d'){const reg=new URLSearchParams(location.search).get('region')||'motion';ui.activeAdventure=reg;goto('adventure-3d',{activeAdventure:reg});}if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(reg=>{reg.update?.();if(reg.waiting){swUpdate=reg.waiting;render();}reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){swUpdate=worker;render();}});});}).catch(()=>notify('Offline installation is unavailable. You can still play online.'));let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swUpdate&&!refreshing&&!saveError){refreshing=true;location.reload();}});}}
init();

window.addEventListener('beforeunload',event=>{if(saveError){event.preventDefault();event.returnValue='';}});

app.addEventListener('pointerdown',e=>{const touchWalk=e.target.closest('[data-action="touch-walk"]');const inst=adventure3DInstance||harborWalkInstance;if(touchWalk&&inst){e.preventDefault();try{touchWalk.setPointerCapture(e.pointerId);}catch{}touchWalk.classList.add('is-active');inst.setKey(touchWalk.dataset.dir,true);return;}const handle=e.target.closest('.ramp-height-handle');if(!handle||handle.disabled||ui.view!=='lab'||ui.animation)return;e.preventDefault();handle.setPointerCapture?.(e.pointerId);ui.rampDrag={pointerId:e.pointerId,element:handle,rect:$('.ramp-scene-art svg').getBoundingClientRect()};});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.word){e.preventDefault();closeWord();}});
app.addEventListener('pointermove',e=>{const dpad=e.target.closest('.harbor-walk-dpad, .adventure-3d-dpad');const inst=adventure3DInstance||harborWalkInstance;if(dpad&&inst&&e.buttons>0){const elem=document.elementFromPoint(e.clientX,e.clientY);const targetBtn=elem?.closest('[data-action="touch-walk"]');for(const dir of ['forward','backward','left','right']){const btn=dpad.querySelector(`[data-dir="${dir}"]`);const isTarget=!!(targetBtn&&targetBtn.dataset.dir===dir);if(btn)btn.classList.toggle('is-active',isTarget);inst.setKey(dir,isTarget);}}const d=ui.rampDrag;if(!d||e.pointerId!==d.pointerId)return;const h=heightFromPointer(d.rect,e.clientY);if(h!==ui.lab.input)setInput(h,true);});
for(const name of ['pointerup','pointercancel'])app.addEventListener(name,e=>{const inst=adventure3DInstance||harborWalkInstance;document.querySelectorAll('.touch-btn.is-active').forEach(b=>{b.classList.remove('is-active');try{b.releasePointerCapture(e.pointerId);}catch{}});if(inst)['forward','backward','left','right'].forEach(d=>inst.setKey(d,false));const d=ui.rampDrag;if(d?.pointerId===e.pointerId){d.element.releasePointerCapture?.(e.pointerId);ui.rampDrag=null;}});
window.addEventListener('blur',()=>{const inst=adventure3DInstance||harborWalkInstance;if(inst)['forward','backward','left','right'].forEach(d=>inst.setKey(d,false));document.querySelectorAll('.touch-btn.is-active').forEach(b=>b.classList.remove('is-active'));});
window.addEventListener('blur',()=>{const inst=adventure3DInstance||harborWalkInstance;if(inst){['forward','backward','left','right'].forEach(d=>inst.setKey(d,false));document.querySelectorAll('.touch-btn.is-active').forEach(b=>b.classList.remove('is-active'));}});
app.addEventListener('keydown',e=>{if(!e.target.closest('.ramp-height-handle')||ui.view!=='lab'||ui.animation)return;let value=ui.lab.input;const moves={ArrowUp:.05,ArrowRight:.05,ArrowDown:-.05,ArrowLeft:-.05,PageUp:.1,PageDown:-.1};if(e.key in moves)value+=moves[e.key];else if(e.key==='Home')value=.1;else if(e.key==='End')value=.5;else return;e.preventDefault();setInput(Number(snapRampHeight(value).toFixed(2)));$('.ramp-height-handle')?.focus();});
